/* ==========================================================================
   Vitrine de Páginas — Revolução Concursos
   Preview interno (noindex). Tokens herdados do design system da página de
   vendas (paginas/pagina-de-vendas/design/estilo.css) + tema "colorido".
   ========================================================================== */

/* --- Fontes (servidas do próprio site) --- */
@font-face { font-family: "Mundial"; src: url("/k/fontes/mundial-regular.woff2") format("woff2"); font-weight: 400; font-style: normal; font-display: swap; }
@font-face { font-family: "Mundial"; src: url("/k/fontes/mundial-italic.woff2") format("woff2"); font-weight: 400; font-style: italic; font-display: swap; }
@font-face { font-family: "Mundial"; src: url("/k/fontes/mundial-demibold.woff2") format("woff2"); font-weight: 500 600; font-style: normal; font-display: swap; }
@font-face { font-family: "Mundial"; src: url("/k/fontes/mundial-bold.woff2") format("woff2"); font-weight: 700 800; font-style: normal; font-display: swap; }
@font-face { font-family: "Mundial"; src: url("/k/fontes/mundial-black.woff2") format("woff2"); font-weight: 900; font-style: normal; font-display: swap; }

/* --- Primitivos --- */
:root {
  --rev-purple-50: #F8F2FB; --rev-purple-100: #EEDCF5; --rev-purple-200: #D9B6E8;
  --rev-purple-300: #C48EDB; --rev-purple-400: #AE65CE; --rev-purple-500: #9126C5;
  --rev-purple-600: #72189E; --rev-purple-700: #551277; --rev-purple-800: #3C0E52;
  --rev-purple-900: #25082F; --rev-purple-950: #10071D;

  --rev-orange-100: #FFE8D8; --rev-orange-300: #FF9A5C; --rev-orange-400: #FD7D32;
  --rev-orange-500: #FD6A18; --rev-orange-600: #E85A00; --rev-orange-700: #C94700;

  --rev-cyan-400: #43E6EE; --rev-cyan-500: #22D3EE; --rev-cyan-600: #0891B2;
  --rev-magenta-400: #BB52ED; --rev-magenta-500: #A73FD6;

  --rev-white: #FFFFFF; --rev-neutral-50: #F7F7FA; --rev-neutral-100: #F1F1F4;
  --rev-neutral-200: #E4E4E7; --rev-neutral-300: #D4D4D8; --rev-neutral-400: #A1A1AA;
  --rev-neutral-500: #71717A; --rev-neutral-600: #52525B; --rev-neutral-700: #3F3F46;
  --rev-neutral-800: #27272A; --rev-neutral-900: #18181B;

  --rev-success: #168A5B; --rev-success-bg: #E8F6F0;

  /* Tipografia */
  --rev-font-heading: "Mundial", "Poppins", "Inter", system-ui, sans-serif;
  --rev-font-body: "Mundial", "Poppins", "Inter", system-ui, sans-serif;

  /* Raios, sombras, motion */
  --rev-radius-sm: 0.5rem; --rev-radius-md: 0.75rem; --rev-radius-lg: 1rem;
  --rev-radius-xl: 1.5rem; --rev-radius-pill: 999rem;
  --rev-shadow-sm: 0 1px 2px rgba(16, 7, 29, 0.08);
  --rev-shadow-md: 0 8px 24px rgba(16, 7, 29, 0.12);
  --rev-shadow-lg: 0 16px 48px rgba(16, 7, 29, 0.18);
  --rev-shadow-ai: 0 10px 30px rgba(145, 38, 197, 0.28);
  --rev-glow-focus: 0 0 0 3px rgba(67, 230, 238, 0.45);
  --rev-duration: 200ms;
  --rev-ease: cubic-bezier(0.2, 0, 0, 1);
}

/* --- Tema LIGHT (padrão) --- */
:root, [data-theme="light"] {
  --rev-bg-canvas: #F7F7FA;
  --rev-bg-gradient: linear-gradient(168deg, #F8F5FC 0%, #F1EAF9 48%, #E9DFF5 100%);
  --rev-bg-surface: #FFFFFF;
  --rev-bg-subtle: #F1F1F4;
  --rev-bg-warm: #FFF1E7;
  --rev-text-primary: #10071D;
  --rev-text-secondary: #52525B;
  --rev-text-muted: #71717A;
  --rev-text-brand: #3C0E52;
  --rev-border-default: #D4D4D8;
  --rev-border-focus: #43E6EE;
  --rev-action-primary: #3C0E52;
  --rev-action-primary-hover: #551277;
  --rev-action-primary-fg: #FFFFFF;
  --rev-action-accent: #FD6A18;
  --rev-action-accent-hover: #FD7D32;
  --rev-action-accent-fg: #FFFFFF;

  /* Hero por tema */
  --vt-hero-bg: #FBFAFD;
  --vt-hero-fg: #10071D;
  --vt-hero-muted: #52525B;
  --vt-hero-chip-bg: #EEDCF5;
  --vt-hero-chip-fg: #551277;
  --vt-cta-bg: linear-gradient(135deg, #3C0E52 0%, #72189E 60%, #9126C5 100%);
  --vt-cta-fg: #FFFFFF;
  --vt-form-bg: #FFFFFF;
}

/* --- Tema DARK --- */
[data-theme="dark"] {
  --rev-bg-canvas: #10071D;
  --rev-bg-gradient: linear-gradient(168deg, #10071D 0%, #1D092C 100%);
  --rev-bg-surface: #1D092C;
  --rev-bg-subtle: #3D0E55;
  --rev-bg-warm: #3A1C19;
  --rev-text-primary: #FAFAFA;
  --rev-text-secondary: #C4C1CB;
  --rev-text-muted: #9B93A2;
  --rev-text-brand: #D9B6E8;
  --rev-border-default: #4A2973;
  --rev-border-focus: #43E6EE;
  --rev-action-primary: #9126C5;
  --rev-action-primary-hover: #AE65CE;
  --rev-action-primary-fg: #FFFFFF;
  --rev-action-accent: #FD6A18;
  --rev-action-accent-hover: #FD7D32;
  --rev-action-accent-fg: #FFFFFF;
  --rev-success-bg: #0E3327;

  --vt-hero-bg: radial-gradient(80rem 40rem at 70% -10%, rgba(145, 38, 197, 0.35), transparent 60%), linear-gradient(168deg, #10071D 0%, #1D092C 100%);
  --vt-hero-fg: #FAFAFA;
  --vt-hero-muted: #C4C1CB;
  --vt-hero-chip-bg: #3D0E55;
  --vt-hero-chip-fg: #D9B6E8;
  --vt-cta-bg: radial-gradient(60rem 30rem at 30% 120%, rgba(253, 106, 24, 0.28), transparent 55%), linear-gradient(135deg, #25082F 0%, #3C0E52 100%);
  --vt-cta-fg: #FAFAFA;
  --vt-form-bg: #1D092C;
}

/* --- Tema COLORIDO: chips de ícone precisam de cor própria (o chip do hero
       é branco translúcido e sumiria sobre cards brancos) --- */
[data-theme="colorido"] .vt-card .vt-icon,
[data-theme="colorido"] .b-card .b-icon,
[data-theme="colorido"] .b-quote .b-avatar {
  background: linear-gradient(135deg, #EEDCF5, #FFE8D8);
  color: #72189E;
}

/* --- Tema COLORIDO --- */
[data-theme="colorido"] {
  --rev-bg-canvas: #FFF6F0;
  --rev-bg-gradient: linear-gradient(160deg, #FFF1E7 0%, #F8F2FB 55%, #E9DFF5 100%);
  --rev-bg-surface: #FFFFFF;
  --rev-bg-subtle: #FFE8D8;
  --rev-bg-warm: #FFF1E7;
  --rev-text-primary: #25082F;
  --rev-text-secondary: #52525B;
  --rev-text-muted: #71717A;
  --rev-text-brand: #72189E;
  --rev-border-default: #EEDCF5;
  --rev-border-focus: #43E6EE;
  --rev-action-primary: #FD6A18;
  --rev-action-primary-hover: #FD7D32;
  --rev-action-primary-fg: #FFFFFF;
  --rev-action-accent: #9126C5;
  --rev-action-accent-hover: #AE65CE;
  --rev-action-accent-fg: #FFFFFF;

  --vt-hero-bg: linear-gradient(130deg, #72189E 0%, #9126C5 38%, #BB52ED 62%, #FD6A18 100%);
  --vt-hero-fg: #FFFFFF;
  --vt-hero-muted: rgba(255, 255, 255, 0.85);
  --vt-hero-chip-bg: rgba(255, 255, 255, 0.18);
  --vt-hero-chip-fg: #FFFFFF;
  --vt-cta-bg: linear-gradient(130deg, #FD6A18 0%, #BB52ED 55%, #72189E 100%);
  --vt-cta-fg: #FFFFFF;
  --vt-form-bg: rgba(255, 255, 255, 0.98);
}

/* ==========================================================================
   Base
   ========================================================================== */
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: var(--rev-font-body);
  font-size: 1rem;
  line-height: 1.55;
  color: var(--rev-text-primary);
  background: var(--rev-bg-canvas);
  transition: background-color var(--rev-duration) var(--rev-ease), color var(--rev-duration) var(--rev-ease);
  -webkit-font-smoothing: antialiased;
}
h1, h2, h3 { font-family: var(--rev-font-heading); line-height: 1.2; margin: 0 0 0.5em; text-wrap: balance; }
p { margin: 0 0 1em; }
a { color: inherit; }
img { max-width: 100%; display: block; }
.container { max-width: 72rem; margin: 0 auto; padding: 0 1.25rem; }

/* ==========================================================================
   Chrome da Vitrine (hub e páginas de tipo)
   ========================================================================== */
.vt-topbar {
  display: flex; align-items: center; gap: 0.85rem;
  padding: 1rem 1.25rem; max-width: 72rem; margin: 0 auto;
}
.vt-topbar img { height: 2rem; width: auto; }
.vt-topbar .vt-title { font-weight: 700; font-size: 1.05rem; color: var(--rev-text-brand); }
.vt-topbar .vt-crumb { color: var(--rev-text-muted); font-size: 0.95rem; text-decoration: none; }
.vt-topbar .vt-crumb:hover { color: var(--rev-text-brand); }
.vt-badge-internal {
  margin-left: auto; font-size: 0.72rem; font-weight: 600; letter-spacing: 0.02em;
  padding: 0.3rem 0.7rem; border-radius: var(--rev-radius-pill);
  background: var(--rev-bg-subtle); color: var(--rev-text-muted);
  border: 1px solid var(--rev-border-default); white-space: nowrap;
}

.vt-hero {
  background: var(--rev-bg-gradient);
  padding: 3.5rem 0 3rem;
  border-bottom: 1px solid var(--rev-border-default);
}
.vt-hero h1 { font-size: clamp(1.8rem, 4vw, 2.6rem); font-weight: 800; color: var(--rev-text-primary); }
.vt-hero p { font-size: 1.1rem; color: var(--rev-text-secondary); max-width: 42rem; }

.vt-grid {
  display: grid; gap: 1.25rem;
  grid-template-columns: repeat(auto-fill, minmax(17rem, 1fr));
  padding: 2.5rem 0 4rem;
}
.vt-card {
  display: flex; flex-direction: column; gap: 0.6rem;
  background: var(--rev-bg-surface);
  border: 1px solid var(--rev-border-default);
  border-radius: var(--rev-radius-lg);
  padding: 1.5rem;
  text-decoration: none;
  box-shadow: var(--rev-shadow-sm);
  transition: transform var(--rev-duration) var(--rev-ease), box-shadow var(--rev-duration) var(--rev-ease), border-color var(--rev-duration) var(--rev-ease);
}
a.vt-card:hover { transform: translateY(-3px); box-shadow: var(--rev-shadow-md); border-color: var(--rev-purple-300); }
.vt-card .vt-icon {
  width: 2.75rem; height: 2.75rem; border-radius: var(--rev-radius-md);
  display: grid; place-items: center;
  background: var(--vt-hero-chip-bg); color: var(--vt-hero-chip-fg);
}
.vt-card .vt-icon svg { width: 1.4rem; height: 1.4rem; }
.vt-card h2, .vt-card h3 { font-size: 1.2rem; font-weight: 700; margin: 0.35rem 0 0; }
.vt-card p { font-size: 0.95rem; color: var(--rev-text-secondary); margin: 0; }
.vt-card .vt-status { margin-top: auto; padding-top: 0.9rem; font-size: 0.78rem; font-weight: 700; }
.vt-status-on { color: var(--rev-success); }
.vt-status-soon { color: var(--rev-text-muted); }
.vt-card--soon { opacity: 0.62; }

/* Hub em lista vertical: uma página por linha */
.vt-list { display: flex; flex-direction: column; gap: 0.85rem; padding: 1.75rem 0 4.5rem; }
.vt-row {
  display: flex; align-items: center; gap: 1.1rem;
  background: var(--rev-bg-surface);
  border: 1px solid var(--rev-border-default);
  border-radius: var(--rev-radius-lg);
  padding: 1.05rem 1.4rem;
  text-decoration: none;
  box-shadow: var(--rev-shadow-sm);
  transition: transform var(--rev-duration) var(--rev-ease), box-shadow var(--rev-duration) var(--rev-ease), border-color var(--rev-duration) var(--rev-ease);
}
a.vt-row:hover { transform: translateY(-2px); box-shadow: var(--rev-shadow-md); border-color: var(--rev-purple-300); }
.vt-row .vt-icon {
  flex: none; width: 2.6rem; height: 2.6rem; border-radius: var(--rev-radius-md);
  display: grid; place-items: center;
  background: var(--vt-hero-chip-bg); color: var(--vt-hero-chip-fg);
}
.vt-row .vt-icon svg { width: 1.3rem; height: 1.3rem; }
.vt-row h2 { font-size: 1.1rem; font-weight: 700; margin: 0; white-space: nowrap; }
.vt-row p { margin: 0; font-size: 0.9rem; color: var(--rev-text-secondary); flex: 1; min-width: 14rem; }
.vt-row .vt-status { margin-left: auto; font-size: 0.78rem; font-weight: 700; white-space: nowrap; }
.vt-row--soon { opacity: 0.62; }
@media (max-width: 47rem) {
  .vt-row { flex-wrap: wrap; }
  .vt-row .vt-status { margin-left: 0; flex-basis: 100%; }
}

/* ==========================================================================
   Barra de preview (voltar + seletor de tema)
   ========================================================================== */
.vt-toolbar {
  position: fixed; bottom: 1rem; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 0.25rem;
  background: rgba(16, 7, 29, 0.92); color: #FAFAFA;
  padding: 0.35rem 0.5rem; border-radius: var(--rev-radius-pill);
  box-shadow: var(--rev-shadow-lg);
  z-index: 50; font-size: 0.85rem;
  backdrop-filter: blur(6px);
  max-width: calc(100vw - 2rem);
}
.vt-toolbar a {
  color: #FAFAFA; text-decoration: none; font-weight: 600;
  padding: 0.35rem 0.75rem; border-radius: var(--rev-radius-pill); white-space: nowrap;
}
.vt-toolbar a:hover { background: rgba(255, 255, 255, 0.12); }
.vt-toolbar .vt-sep { width: 1px; height: 1.2rem; background: rgba(255, 255, 255, 0.25); margin: 0 0.25rem; }
.vt-toolbar button {
  font: inherit; font-weight: 600; cursor: pointer;
  color: #FAFAFA; background: transparent; border: 0;
  padding: 0.35rem 0.75rem; border-radius: var(--rev-radius-pill); white-space: nowrap;
}
.vt-toolbar button:hover { background: rgba(255, 255, 255, 0.12); }
.vt-toolbar button[aria-pressed="true"] { background: var(--rev-purple-500); }

/* ==========================================================================
   Blocos de landing page (usados no modelo e na galeria de blocos)
   ========================================================================== */

/* --- Bloco: Hero de captura com formulário --- */
.b-hero { background: var(--vt-hero-bg); color: var(--vt-hero-fg); padding: 4rem 0; }
.b-hero .container { display: grid; gap: 2.5rem; grid-template-columns: 1.15fr 0.85fr; align-items: center; max-width: 62rem; padding: 0 2rem; }
.b-hero .b-chip {
  display: inline-block; font-size: 0.8rem; font-weight: 700; letter-spacing: 0.04em;
  text-transform: uppercase; padding: 0.35rem 0.85rem; border-radius: var(--rev-radius-pill);
  background: var(--vt-hero-chip-bg); color: var(--vt-hero-chip-fg); margin-bottom: 1rem;
}
.b-hero h1 { font-size: clamp(1.9rem, 4.5vw, 3rem); font-weight: 800; color: var(--vt-hero-fg); }
.b-hero .b-sub { font-size: 1.15rem; color: var(--vt-hero-muted); max-width: 34rem; }
.b-hero .b-mini { font-size: 0.85rem; color: var(--vt-hero-muted); margin: 0.75rem 0 0; }

.b-form {
  background: var(--vt-form-bg); color: var(--rev-text-primary);
  border-radius: var(--rev-radius-xl); padding: 1.75rem;
  box-shadow: var(--rev-shadow-lg); border: 1px solid var(--rev-border-default);
  display: grid; gap: 0.9rem;
}
.b-form h2 { font-size: 1.15rem; margin: 0; }
.b-form label { font-size: 0.85rem; font-weight: 600; color: var(--rev-text-secondary); display: grid; gap: 0.3rem; }
.b-form input {
  font: inherit; width: 100%;
  padding: 0.8rem 1rem; border-radius: var(--rev-radius-md);
  border: 1px solid var(--rev-border-default);
  background: var(--rev-bg-surface); color: var(--rev-text-primary);
}
.b-form input:focus { outline: none; border-color: var(--rev-border-focus); box-shadow: var(--rev-glow-focus); }
.b-form .b-success {
  display: none; text-align: center; padding: 1rem 0.5rem;
  background: var(--rev-success-bg); color: var(--rev-success);
  border-radius: var(--rev-radius-md); font-weight: 700;
}
.b-form.enviado form { display: none; }
.b-form.enviado .b-success { display: block; }

.b-btn {
  font: inherit; font-weight: 700; font-size: 1.05rem; cursor: pointer;
  display: inline-block; text-align: center; text-decoration: none;
  padding: 0.95rem 1.75rem; border: 0; border-radius: var(--rev-radius-md);
  background: var(--rev-action-primary); color: var(--rev-action-primary-fg);
  transition: background var(--rev-duration) var(--rev-ease), transform var(--rev-duration) var(--rev-ease);
}
.b-btn:hover { background: var(--rev-action-primary-hover); transform: translateY(-1px); }
.b-btn--accent { background: var(--rev-action-accent); color: var(--rev-action-accent-fg); }
.b-btn--accent:hover { background: var(--rev-action-accent-hover); }
/* botão laranja padrão da plataforma: cantos de 8px e borda inferior mais escura */
.b-btn--accent, .b-cta .b-btn { border-radius: 8px; box-shadow: 0 3px 0 #C94700; }
[data-theme="colorido"] .b-cta .b-btn { box-shadow: none; }

/* --- Bloco: Barra de confiança (números) --- */
.b-trust { background: var(--rev-bg-surface); border-bottom: 1px solid var(--rev-border-default); padding: 1.5rem 0; }
.b-trust .container { display: flex; flex-wrap: wrap; gap: 1rem 3rem; justify-content: center; text-align: center; }
.b-trust .b-num { font-size: 1.4rem; font-weight: 800; color: var(--rev-text-brand); }
.b-trust .b-label { font-size: 0.85rem; color: var(--rev-text-muted); }

/* --- Estrutura padrão de seção --- */
.b-section { padding: 4rem 0; }
.b-section--alt { background: var(--rev-bg-surface); }
.b-kicker {
  font-size: 0.8rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--rev-action-accent); margin-bottom: 0.5rem;
}
[data-theme="colorido"] .b-kicker { color: var(--rev-purple-500); }
.b-section h2 { font-size: clamp(1.5rem, 3vw, 2.1rem); font-weight: 800; }
.b-section .b-intro { color: var(--rev-text-secondary); max-width: 40rem; font-size: 1.05rem; }

/* --- Bloco: Benefícios (cards) --- */
.b-cards { display: grid; gap: 1.25rem; grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); margin-top: 2rem; }
.b-card {
  background: var(--rev-bg-surface); border: 1px solid var(--rev-border-default);
  border-radius: var(--rev-radius-lg); padding: 1.5rem; box-shadow: var(--rev-shadow-sm);
}
.b-section--alt .b-card { background: var(--rev-bg-canvas); }
.b-card .b-icon {
  width: 2.6rem; height: 2.6rem; border-radius: var(--rev-radius-md);
  display: grid; place-items: center; margin-bottom: 0.9rem;
  background: var(--vt-hero-chip-bg); color: var(--vt-hero-chip-fg);
}
.b-card .b-icon svg { width: 1.3rem; height: 1.3rem; }
.b-card h3 { font-size: 1.1rem; font-weight: 700; }
.b-card p { font-size: 0.95rem; color: var(--rev-text-secondary); margin: 0; }

/* --- Bloco: Passo a passo --- */
.b-steps { display: grid; gap: 1.25rem; grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr)); margin-top: 2rem; counter-reset: passo; }
.b-step { position: relative; padding: 1.5rem; border-radius: var(--rev-radius-lg); background: var(--rev-bg-surface); border: 1px solid var(--rev-border-default); }
.b-section--alt .b-step { background: var(--rev-bg-canvas); }
.b-step::before {
  counter-increment: passo; content: counter(passo);
  display: grid; place-items: center; width: 2.2rem; height: 2.2rem; margin-bottom: 0.9rem;
  border-radius: var(--rev-radius-pill); font-weight: 800;
  background: var(--rev-action-primary); color: var(--rev-action-primary-fg);
}
.b-step h3 { font-size: 1.05rem; font-weight: 700; }
.b-step p { font-size: 0.95rem; color: var(--rev-text-secondary); margin: 0; }

/* --- Bloco: Prova social (depoimentos) --- */
.b-quotes { display: grid; gap: 1.25rem; grid-template-columns: repeat(auto-fit, minmax(18rem, 1fr)); margin-top: 2rem; }
.b-quote {
  background: var(--rev-bg-surface); border: 1px solid var(--rev-border-default);
  border-radius: var(--rev-radius-lg); padding: 1.5rem; box-shadow: var(--rev-shadow-sm);
  display: grid; gap: 0.9rem;
}
.b-section--alt .b-quote { background: var(--rev-bg-canvas); }
.b-quote .b-stars { color: var(--rev-orange-500); font-size: 1rem; letter-spacing: 0.15em; }
.b-quote blockquote { margin: 0; font-size: 1rem; color: var(--rev-text-primary); }
.b-quote .b-who { display: flex; align-items: center; gap: 0.75rem; }
.b-quote .b-avatar {
  width: 2.5rem; height: 2.5rem; border-radius: var(--rev-radius-pill);
  display: grid; place-items: center; font-weight: 800; font-size: 0.9rem;
  background: var(--vt-hero-chip-bg); color: var(--vt-hero-chip-fg);
}
.b-quote .b-name { font-weight: 700; font-size: 0.95rem; }
.b-quote .b-role { font-size: 0.8rem; color: var(--rev-text-muted); }

/* --- Bloco: FAQ --- */
.b-faq { max-width: 46rem; margin: 2rem auto 0; display: grid; gap: 0.75rem; }
.b-faq details {
  background: var(--rev-bg-surface); border: 1px solid var(--rev-border-default);
  border-radius: var(--rev-radius-md); padding: 1rem 1.25rem;
}
.b-section--alt .b-faq details { background: var(--rev-bg-canvas); }
.b-faq summary { font-weight: 700; cursor: pointer; list-style: none; display: flex; justify-content: space-between; align-items: center; gap: 1rem; }
.b-faq summary::after { content: "+"; font-size: 1.3rem; font-weight: 400; color: var(--rev-text-muted); transition: transform var(--rev-duration) var(--rev-ease); }
.b-faq details[open] summary::after { transform: rotate(45deg); }
.b-faq details p { margin: 0.75rem 0 0; color: var(--rev-text-secondary); font-size: 0.95rem; }

/* --- Bloco: CTA final --- */
.b-cta { background: var(--vt-cta-bg); color: var(--vt-cta-fg); padding: 4.5rem 0; text-align: center; }
.b-cta h2 { font-size: clamp(1.6rem, 3.5vw, 2.4rem); font-weight: 800; color: var(--vt-cta-fg); }
.b-cta p { color: var(--vt-cta-fg); opacity: 0.88; max-width: 36rem; margin: 0 auto 1.75rem; font-size: 1.1rem; }
.b-cta .b-btn { background: var(--rev-action-accent); color: var(--rev-action-accent-fg); }
.b-cta .b-btn:hover { background: var(--rev-action-accent-hover); }
[data-theme="colorido"] .b-cta .b-btn { background: #FFFFFF; color: var(--rev-purple-600); }
[data-theme="colorido"] .b-cta .b-btn:hover { background: #F8F2FB; }

/* --- Bloco: Rodapé mini --- */
.b-footer { padding: 2.5rem 0; text-align: center; color: var(--rev-text-muted); font-size: 0.85rem; }
.b-footer img { height: 1.6rem; width: auto; margin: 0 auto 0.75rem; }
[data-theme="dark"] .b-footer img { filter: brightness(0) invert(1); opacity: 0.7; }

/* ==========================================================================
   Galeria de blocos (páginas /blocos/)
   ========================================================================== */
.vt-frame { margin: 1.6rem 0; }
.vt-frame-head { max-width: 72rem; margin: 0 auto 0.75rem; padding: 0 1.25rem; display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.6rem; }
.vt-frame-head .vt-frame-tag {
  font-size: 0.72rem; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase;
  background: var(--rev-purple-500); color: #FFFFFF;
  padding: 0.25rem 0.65rem; border-radius: var(--rev-radius-pill);
}
.vt-frame-head h2 { font-size: 1.15rem; margin: 0; }
.vt-frame-head p { font-size: 0.9rem; color: var(--rev-text-muted); margin: 0; flex-basis: 100%; }
.vt-frame-body { border: 1px dashed var(--rev-border-default); border-radius: var(--rev-radius-lg); overflow: hidden; max-width: 76rem; margin: 0 auto; }

/* ==========================================================================
   Responsivo
   ========================================================================== */
@media (max-width: 47rem) {
  .b-hero { padding: 3rem 0; }
  .b-hero .container { grid-template-columns: 1fr; gap: 2rem; }
  .b-section { padding: 3rem 0; }
  .vt-topbar { flex-wrap: wrap; }
  .vt-badge-internal { margin-left: 0; }
  .vt-toolbar { font-size: 0.78rem; }
}

/* Bancadas: clique numa miniatura para expandir em tela cheia */
.vt-mini { cursor: zoom-in; }
.vt-expandido { position: fixed; inset: 0; z-index: 100; background: #FFFFFF; overflow: auto; }
.vt-expandido-barra {
  position: sticky; top: 0; z-index: 2;
  display: flex; justify-content: space-between; align-items: center; gap: 1rem;
  background: rgba(16, 7, 29, 0.94); color: #FAFAFA;
  padding: 0.6rem 1.1rem; font-size: 0.85rem;
}
.vt-expandido-barra button { font-size: 1.5rem; line-height: 1; background: none; border: 0; color: #FAFAFA; cursor: pointer; padding: 0 0.4rem; }

grupos.css:
      /* Quadro de desmembramento: fundo sempre branco, blocos com cores próprias */
      body { background: #FFFFFF; }

      /* Par dark|white lado a lado, em miniatura 50% que preserva o layout desktop */
      .vt-duo { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 0.8rem; max-width: 74rem; margin: 0 auto; padding: 0 2.5rem; }
      .vt-mini { border: 1px solid #E4E4E7; border-radius: 0.75rem; overflow: hidden; box-shadow: 0 1px 2px rgba(16,7,29,0.08); }
      .vt-mini-inner { width: 200%; transform: scale(0.5); transform-origin: top left; }
      .vt-mini-label { display: flex; align-items: center; gap: 0.5rem; padding: 0.6rem 0.9rem; font-size: 0.8rem; font-weight: 700; color: #52525B; background: #F7F7FA; border-bottom: 1px solid #E4E4E7; }
      .vt-mini-label .dot { width: 0.7rem; height: 0.7rem; border-radius: 999rem; border: 1px solid #D4D4D8; }
      @media (max-width: 60rem) { .vt-duo { grid-template-columns: minmax(0, 1fr); } }

      @keyframes revPulse { 0%,100% { transform: scale(1); opacity: 0.8; } 50% { transform: scale(1.15); opacity: 0.4; } }
      @media (max-width: 720px) { .rev-nav-links { display: none; } }

      .vt-roadmap { display: flex; flex-wrap: wrap; gap: 0.6rem; max-width: 72rem; margin: 0 auto; padding: 0 1.25rem 1rem; }
      .vt-roadmap span { font-size: 0.85rem; font-weight: 600; color: #71717A; background: #F1F1F4; border: 1px dashed #D4D4D8; border-radius: 999rem; padding: 0.4rem 0.9rem; }

      /* Versão white: componentes que no original só existiam no escuro */
      .pv-section--light .pv-node { background: #FFFFFF; border-color: #E4E4E7; }
      .pv-section--light .pv-node__body p { color: #3F3F46; }
      .pv-section--light .pv-tl-item p { color: #3F3F46; }
      .pv-section--light .pv-tl-item h4, .pv-section--light .pv-tl-item .pv-tl-tag { color: #0891B2; }
      .pv-section--light .pv-tl-item::after { background: #FFFFFF; }
      .pv-section--light .pv-table { border-color: #E4E4E7; }
      .pv-section--light .pv-table__row { color: #3F3F46; border-color: #E4E4E7; }
      .pv-section--light .pv-table__row:first-child { background: #F1F1F4; }
      .pv-section--light .pv-table__row--total { color: #10071D; }
      .pv-checks--indark li { color: #C4C1CB !important; }

      /* Sumário de atalhos para os blocos */
      .vt-indice { max-width: 74rem; margin: 0 auto; padding: 0.75rem 2.5rem 0.25rem; display: flex; flex-wrap: wrap; gap: 0.4rem; }
      .vt-indice a { font-size: 0.78rem; font-weight: 600; color: #52525B; background: #F1F1F4; border: 1px solid #E4E4E7; border-radius: 999rem; padding: 0.3rem 0.75rem; text-decoration: none; }
      .vt-indice a:hover { color: #FFFFFF; background: #72189E; border-color: #72189E; }

      /* Bloco de recompensas (cards de produto) */
      .rec-sec { padding: 56px 24px; }
      .rec-sec--dark { background: #140823; color: #FAFAFA; }
      .rec-sec--claro { background: #F7F7FA; color: #18181B; }
      .rec-grid { max-width: 62rem; margin: 0 auto; display: grid; grid-template-columns: repeat(auto-fit, minmax(12.5rem, 1fr)); gap: 1.1rem; }
      .rec-card { position: relative; border-radius: 1rem; overflow: hidden; display: flex; flex-direction: column; background: #FFFFFF; border: 1px solid #E4E4E7; }
      .rec-sec--dark .rec-card { background: #1D092C; border-color: #33184F; }
      .rec-selo { position: absolute; top: 0.8rem; left: 0.8rem; z-index: 1; font-size: 0.62rem; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase; color: #FFFFFF; background: #FD6A18; border-radius: 999rem; padding: 0.3rem 0.7rem; }
      .rec-foto { aspect-ratio: 1 / 1; display: grid; place-items: center; background: linear-gradient(160deg, #F8F2FB, #FFE8D8); }
      .rec-sec--dark .rec-foto { background: linear-gradient(160deg, #25082F, #3A1C19); }
      .rec-foto { overflow: hidden; }
      .rec-foto img { width: 100%; height: 100%; object-fit: cover; }
      .rec-cartao { width: 55%; aspect-ratio: 3 / 4; border-radius: 0.8rem; background: linear-gradient(170deg, #FD7D32, #E85A00); display: grid; place-items: center; color: #FFFFFF; font-weight: 900; font-size: 1.3rem; box-shadow: 0 10px 24px rgba(232, 90, 0, 0.35); }
      .rec-vaga { width: 62%; aspect-ratio: 1 / 1; border-radius: 0.8rem; border: 2px dashed rgba(120, 90, 140, 0.4); display: grid; place-items: center; text-align: center; font-size: 0.72rem; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; color: rgba(120, 90, 140, 0.7); }
      .rec-sec--dark .rec-vaga { border-color: rgba(255, 255, 255, 0.3); color: rgba(255, 255, 255, 0.45); }
      .rec-corpo { padding: 1rem 1.1rem 1.2rem; display: flex; flex-direction: column; gap: 0.55rem; flex: 1; }
      .rec-corpo h3 { margin: 0; font-size: 1.02rem; font-weight: 800; }
      .rec-corpo p { margin: 0; font-size: 0.85rem; line-height: 1.5; color: #52525B; flex: 1; }
      .rec-sec--dark .rec-corpo p { color: #C4C1CB; }
      .rec-preco { align-self: flex-start; font-size: 0.78rem; font-weight: 700; color: #168A5B; background: #E8F6F0; border-radius: 999rem; padding: 0.25rem 0.75rem; }
      .rec-sec--dark .rec-preco { color: #3ECF8E; background: rgba(62, 207, 142, 0.12); }
      .rec-btn { text-align: center; font-weight: 700; font-size: 0.88rem; border-radius: 0.6rem; padding: 0.65rem; background: #F1F1F4; color: #18181B; text-decoration: none; }
      .rec-sec--dark .rec-btn { background: #3D0E55; color: #FAFAFA; }
      .rec-btn--destaque, .rec-sec--dark .rec-btn--destaque { background: #FD6A18; color: #FFFFFF;border-radius:8px;box-shadow:0 3px 0 #C94700;border-radius:8px;box-shadow:0 3px 0 #C94700}

      /* Oferta em planos */
      .of-sec { padding: 64px 24px; }
      .of-sec--dark { background: #10071D; color: #FAFAFA; }
      .of-sec--claro { background: #F7F7FA; color: #18181B; }
      .of-titulo { margin: 0 auto; max-width: 40rem; text-align: center; font-size: clamp(1.6rem, 3vw, 2.2rem); font-weight: 900; }
      .of-titulo b { color: #FD6A18; }
      .of-grid { max-width: 72rem; margin: 2.2rem auto 0; display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 1.4rem; align-items: stretch; }
      .of-card { position: relative; border-radius: 1rem; overflow: hidden; display: flex; flex-direction: column; background: #1D092C; border: 1px solid #33184F; }
      .of-sec--claro .of-card { background: #FFFFFF; border-color: #E4E4E7; }
      .of-card--destaque { border-color: #73E3ED; box-shadow: 0 0 32px rgba(115, 227, 237, 0.35); }
      .of-faixa { position: absolute; top: 1.4rem; right: -3.2rem; transform: rotate(38deg); background: #FD6A18; color: #FFFFFF; font-size: 0.66rem; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; padding: 0.4rem 3.6rem; }
      .of-mockup { aspect-ratio: 16 / 10; display: grid; place-items: center; background: linear-gradient(160deg, #25082F, #0C0514); }
      .of-sec--claro .of-mockup { background: linear-gradient(160deg, #F8F2FB, #EEDCF5); }
      .of-mockup span { width: 70%; aspect-ratio: 16 / 9; border-radius: 0.7rem; border: 2px dashed rgba(255, 255, 255, 0.3); display: grid; place-items: center; font-size: 0.7rem; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: rgba(255, 255, 255, 0.45); }
      .of-sec--claro .of-mockup span { border-color: rgba(60, 14, 82, 0.3); color: rgba(60, 14, 82, 0.5); }
      .of-corpo { padding: 1.5rem 1.5rem 1.7rem; display: flex; flex-direction: column; align-items: center; text-align: center; gap: 0.4rem; flex: 1; }
      .of-chip { font-size: 0.68rem; font-weight: 700; letter-spacing: 0.16em; text-transform: uppercase; color: #FD6A18; background: rgba(253, 106, 24, 0.1); border: 1px solid rgba(253, 106, 24, 0.4); border-radius: 0.4rem; padding: 0.4rem 1rem; margin-bottom: 0.5rem; }
      .of-de { text-decoration: line-through; color: #9B93A2; font-size: 0.9rem; }
      .of-sec--claro .of-de { color: #A1A1AA; }
      .of-por { font-size: 0.95rem; }
      .of-preco { font-size: 2.7rem; font-weight: 900; line-height: 1; color: #FD6A18; }
      .of-vista { font-size: 0.85rem; color: #9B93A2; }
      .of-sec--claro .of-vista { color: #71717A; }
      .of-lista { list-style: none; margin: 1rem 0 1.2rem; padding: 0; display: flex; flex-direction: column; gap: 0.45rem; text-align: left; font-size: 0.9rem; }
      .of-lista li { display: flex; gap: 0.5rem; }
      .of-lista li::before { content: "✓"; color: #FD6A18; font-weight: 800; flex: none; }
      .of-btn { margin-top: auto; width: 100%; text-align: center; text-decoration: none; font-weight: 700; font-size: 0.95rem; text-transform: uppercase; letter-spacing: 0.08em; color: #FFFFFF; background:#FD6A18; border-radius:8px; padding: 0.85rem; box-shadow:0 3px 0 #C94700; }

      /* Prova social em texto */
      .ps-sec { padding: 60px 24px; }
      .ps-sec--dark { background: radial-gradient(1100px 620px at 50% 100%, rgba(160,96,235,0.55) 0%, rgba(108,58,173,0.28) 42%, transparent 72%), linear-gradient(180deg,#0F071C,#170A28); color: #FAFAFA; }
      .ps-sec--claro { background: #FBFAFD; color: #18181B; }
      .ps-kicker { text-align: center; font-size: 0.75rem; font-weight: 700; letter-spacing: 0.18em; text-transform: uppercase; color: #FD6A18; margin: 0 0 0.5rem; }
      .ps-titulo { margin: 0 auto; max-width: 38rem; text-align: center; font-size: clamp(1.4rem, 2.6vw, 1.9rem); font-weight: 900; }
      .ps-grid { max-width: 60rem; margin: 2rem auto 0; display: grid; grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); gap: 1.1rem; }
      .ps-card { border-radius: 1rem; padding: 1.4rem; display: flex; flex-direction: column; gap: 0.8rem; background: #1D092C; border: 1px solid #33184F; }
      .ps-sec--claro .ps-card { background: #F7F7FA; border-color: #E4E4E7; }
      .ps-aspas { font-size: 2.2rem; font-weight: 900; line-height: 0.6; color: #FD6A18; }
      .ps-texto { margin: 0; font-size: 0.95rem; line-height: 1.6; color: #E8E2EF; flex: 1; }
      .ps-sec--claro .ps-texto { color: #3F3F46; }
      .ps-estrelas { color: #FD6A18; letter-spacing: 0.15em; font-size: 0.9rem; }
      .ps-quem { margin: 0; font-size: 0.85rem; font-weight: 700; }
      .ps-quem small { display: block; font-weight: 500; color: #9B93A2; }
      .ps-sec--claro .ps-quem small { color: #71717A; }

      /* Prova social em vídeo */
      .pv2-video { aspect-ratio: 16 / 9; border-radius: 0.8rem; overflow: hidden; position: relative; display: grid; place-items: center; background: radial-gradient(ellipse at center, #2A1740 0%, #0C0514 80%); border: 1px solid #33184F; }
      .ps-sec--claro .pv2-video { border-color: #E4E4E7; }
      .pv2-play { width: 3.4rem; height: 3.4rem; border-radius: 999rem; display: grid; place-items: center; background: linear-gradient(135deg, #FD7D32, #E85A00); box-shadow: 0 8px 26px rgba(253, 106, 24, 0.5); }
      .pv2-play svg { width: 1rem; height: 1.2rem; margin-left: 2px; }
      .pv2-tempo { position: absolute; bottom: 0.6rem; right: 0.7rem; font-size: 0.68rem; font-weight: 700; color: #FFFFFF; background: rgba(0, 0, 0, 0.55); border-radius: 0.3rem; padding: 0.15rem 0.45rem; }
          /* Ajustes para celular */
      @media (max-width: 640px) {
        .vt-duo { padding: 0 0.9rem; gap: 1rem; }
        .vt-frame-head { padding-left: 0.35rem; padding-right: 0.35rem; }
        body > .container { padding-left: 1rem !important; padding-right: 1rem !important; }
        body > .container h1 { font-size: 1.35rem !important; }
        .vt-indice { padding-left: 1rem; padding-right: 1rem; }
      }
      /* Whites suaves padronizados (pedido do Kleber, 17/09) */
      .pv-section--light { background: #FBFAFD; }
      .pv-section--soft { background: #FBFAFD; }

      /* Bloco 21: play por cima da foto e brilho roxo atrás dos cartões */
      .pv2-play { position: relative; z-index: 2; }
      .ps-grid { position: relative; }
      .ps-grid::before { content: ""; position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
        width: 88%; height: 130%; border-radius: 999rem; pointer-events: none;
        background: radial-gradient(closest-side, rgba(145, 38, 197, 0.45), transparent 72%); filter: blur(10px); }
      /* versão clara: sem brilho roxo atrás dos cartões e com o nome em cor escura (ficava claro sobre claro) */
      .ps-sec--claro .ps-grid::before { display: none; }
      .ps-sec--claro .ps-quem { color: #18181B; }
      .ps-card { position: relative; }

      /* Bloco 19: teste do botão azul nos planos */
      .of-card .of-btn { background: linear-gradient(180deg, #2E9FEF 0%, #1173C4 100%); box-shadow: 0 10px 26px rgba(21, 140, 230, 0.45); }

      /* FAQ dark: cartões escuros no estilo do quiz (pedido do Kleber, 17/09) */
      .pv-section--dark .pv-faq { background: rgba(255,255,255,0.05); border: 1px solid rgba(237,116,47,0.7); }
      .pv-section--dark .pv-faq summary { color: #FAFAFA; }
      .pv-section--dark .pv-faq p { color: #C4C1CB; }
      .pv-section--dark .pv-faq .faq-chev { color: #ED742F !important; }
      .pv-section--dark .pv-faq:hover, .pv-section--dark .pv-faq[open] { border-color: #ED742F; box-shadow: 0 0 18px rgba(237,116,47,0.25); }

      /* Bloco 15 (FAQ numerado, modelo mandado pelo Kleber): número da
         pergunta + ícone circular +/× que troca sozinho com [open] do <details> */
      .faq15 { counter-reset: faq15; }
      .faq15 .pv-faq { counter-increment: faq15; position: relative; padding-left: 62px; }
      .faq15 .pv-faq::before {
        content: counter(faq15, decimal-leading-zero); position: absolute; left: 22px; top: 23px;
        font: 700 0.72rem/1 ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing: 0.04em; color: #9B93A2;
      }
      .faq15 .pv-faq summary { list-style: none; cursor: pointer; }
      .faq15 .pv-faq summary::-webkit-details-marker { display: none; }
      .faq15 .pv-faq .faq-chev { display: none !important; }
      .faq15 .pv-faq summary::after {
        content: "+"; flex-shrink: 0; width: 28px; height: 28px; border-radius: 999rem; border: 1.5px solid #9B93A2;
        display: flex; align-items: center; justify-content: center; font-size: 1.15rem; font-weight: 400; color: #9B93A2; line-height: 1;
      }
      .faq15 .pv-faq[open] summary::after { content: "\2715"; color: #ED742F; border-color: #ED742F; }
      .pv-section--light .faq15 .pv-faq summary::after { border-color: #D4D4D8; color: #71717A; }
      .pv-section--light .faq15 .pv-faq[open] summary::after { color: #9126C5; border-color: #9126C5; }

      /* Indicador animado do mentor (Bloco 12) */
      @keyframes vtPulse { 0% { box-shadow: 0 0 0 0 rgba(253,106,24,0.55); } 70% { box-shadow: 0 0 0 12px rgba(253,106,24,0); } 100% { box-shadow: 0 0 0 0 rgba(253,106,24,0); } }
      @keyframes vtSetaY { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(6px); } }
      /* Mobile geral (pedido do Kleber, 17/09): tudo que é lado a lado
         empilha CENTRALIZADO, e as imagens se adaptam. Imagens posicionadas
         de forma absoluta (cenas, overlays) ficam como estão. */
      @media (max-width: 700px) {
        [style*="grid-template-columns"] { grid-template-columns: 1fr !important; justify-items: center !important; }
        [style*="grid-template-columns"] > * { text-align: center !important; max-width: 100% !important; }
        [style*="grid-template-columns"] img:not([style*="position:absolute"]) {
          max-width: min(100%, 24rem) !important; width: auto !important; height: auto !important;
          margin: 0.6rem auto !important;
        }
        [style*="justify-content:space-between"] { flex-wrap: wrap; justify-content: center !important; gap: 10px; }
        /* Bloco 27: raposa em meio corpo também no celular */
        .b27-palco { min-height: 11rem !important; width: 100% !important; align-self: auto !important; }
        .b27-fox { width: min(82%, 15rem) !important; max-width: none !important; height: auto !important; margin: 0 auto -9% !important; }
        /* Bloco 19: cartões de plano usam classe (.of-grid), não pega no
           seletor genérico de [style*="grid-template-columns"] acima */
        .of-grid { grid-template-columns: 1fr !important; max-width: 22rem !important; gap: 1.4rem !important; }
        /* Carrossel de 3 ofertas no celular (pedido do Kleber, 19/09):
           o plano ativo fica grande no centro, os outros dois aparecem
           menores dos lados espiando. Toca num dos lados pra ele virar
           o principal. Blocos 23 e 24. */
        .ofc-track {
          display: flex !important; grid-template-columns: none !important;
          justify-content: center !important; align-items: center !important;
          gap: 12px !important; overflow: hidden !important; padding: 6px 0 14px !important;
        }
        .ofc-card {
          flex: 0 0 78% !important; max-width: 78% !important;
          transform: scale(0.86); opacity: 0.5;
          transition: transform 0.35s ease, opacity 0.35s ease;
          cursor: pointer;
        }
        .ofc-card img { width: 100% !important; height: 100% !important; max-width: none !important; margin: 0 !important; }
        .ofc-card[data-slot="center"] { order: 1; transform: scale(1); opacity: 1; z-index: 2; cursor: default; }
        .ofc-card[data-slot="left"] { order: 0; }
        .ofc-card[data-slot="right"] { order: 2; }
        /* Revisão de UX mobile (pedido do Kleber, 20/09): o respiro entre
           blocos era herdado do desktop (72-96px) e sobrava espaço vazio
           demais rolando a página. Reduz só o respiro vertical, mantendo
           a margem lateral. */
        [style*="padding:72px 32px"] { padding-top: 44px !important; padding-bottom: 44px !important; }
        [style*="padding:72px 32px 56px"] { padding-top: 44px !important; padding-bottom: 36px !important; }
        [style*="padding:64px 24px 20px"] { padding-top: 40px !important; padding-bottom: 20px !important; }
        [style*="padding:64px 24px 72px"] { padding-top: 40px !important; padding-bottom: 44px !important; }
        [style*="padding:64px 32px"] { padding-top: 40px !important; padding-bottom: 40px !important; }
        [style*="padding:88px 32px"] { padding-top: 52px !important; padding-bottom: 52px !important; }
        [style*="padding:88px 24px"] { padding-top: 52px !important; padding-bottom: 52px !important; }
        [style*="padding:96px 24px"] { padding-top: 56px !important; padding-bottom: 56px !important; }
        [style*="padding:72px 24px"] { padding-top: 44px !important; padding-bottom: 44px !important; }
      }
      /* Mobile: sem enfeites absolutos que ficam tortos com tudo empilhado */
      @media (max-width: 700px) {
        svg[style*="pointer-events:none"][style*="position:absolute"] { display: none !important; }
        [style*="grid-template-columns"] > svg[style*="position:absolute"] { display: none !important; }
        [style*="flex-direction:row-reverse"] { flex-direction: row !important; text-align: left !important; }
        .rec-grid { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; }
        /* Bloco 22: os 6 itens de funcionalidade (ícone + texto em linha,
           "apontando" pro celular no desktop) ficavam com texto grudado
           à esquerda e espaço vazio sobrando à direita. Centraliza ícone
           em cima do texto — usa :has() pra não pegar o card do Bloco 16,
           que reusa o mesmo gap/align-items mas é um bloco de texto. */
        [style*="gap:16px;align-items:flex-start"]:has(> span > svg) {
          flex-direction: column !important; align-items: center !important;
          text-align: center !important; gap: 10px !important;
        }
      }

      /* Time Revolução (Bloco 28, modelo mandado pelo Kleber): duas fileiras
         de professores rolando sozinhas, uma pra cada lado, sem parar */
      .tr-row { overflow: hidden; -webkit-mask-image: linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent); mask-image: linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent); }
      .tr-track { display: flex; gap: 16px; width: max-content; animation: tr-left 32s linear infinite; }
      .tr-track--reverse { animation: tr-right 32s linear infinite; }
      .tr-row:hover .tr-track { animation-play-state: paused; }
      @keyframes tr-left { from { transform: translateX(0); } to { transform: translateX(-50%); } }
      @keyframes tr-right { from { transform: translateX(-50%); } to { transform: translateX(0); } }
      @media (prefers-reduced-motion: reduce) { .tr-track { animation: none; } }

