/* Página completa — VSL 10. Componentes independentes da bancada original. */
.policial .b-police-full { background:var(--police-canvas); color:#fff; padding:84px 0; }
.policial .full-purple { background:var(--police-canvas); }
.full-split { display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr); gap:64px; align-items:center; }
.body-copy { color:#aebcc8; font-size:14px; line-height:1.9; }
.feature-list,.offer-checklist { padding:0; margin:26px 0 32px; list-style:none; }
.feature-list li,.offer-checklist li { position:relative; padding:0 0 16px 26px; color:#c6d2dd; font-size:13px; line-height:1.7; }
.feature-list li:before,.offer-checklist li:before { content:'✓'; position:absolute; left:0; color:#3ea4f5; }
.origin-visual { padding:38px; border-left:1px solid #6d99c04d; }
.ui-tag { color:#b0c8dd; font-size:9px; letter-spacing:1px; }
.origin-word { margin:26px 0 35px; font-size:clamp(30px,3.4vw,45px); font-weight:700; line-height:1.3; letter-spacing:-1.6px; }
.origin-word em { font-style:normal; color:#3ea4f5; }
.origin-pillars { display:flex; flex-wrap:wrap; gap:8px; }
.origin-pillars span { border:1px solid #406c9377; border-radius:4px; padding:9px 11px; color:#b6c7d5; font-size:10px; }
.ui-panel { border:1px solid #3c628366; background:linear-gradient(145deg,#152a3c,#0d1923); padding:28px; border-radius:10px; box-shadow:0 22px 65px #0003; }
.ui-top { display:flex; justify-content:space-between; align-items:center; gap:14px; border-bottom:1px solid #77a5ce22; padding-bottom:20px; font-size:9px; letter-spacing:1px; color:#cbdcea; }
.ui-panel h3 { font-size:22px; font-weight:600; line-height:1.3; letter-spacing:-.5px; margin:25px 0 20px; }
.time-options { display:flex; gap:8px; }
.time-options button { cursor:pointer; flex:1; background:#000000; border:1px solid #406c9366; padding:12px 5px; color:#b8cddf; border-radius:4px; font-size:12px; }
.time-options button[aria-pressed=true] { background:#185f9e; border-color:#659dce; color:white; }
.session-title { display:flex; justify-content:space-between; gap:12px; padding:28px 0 10px; font-size:9px; letter-spacing:1px; color:#aabbca; }
.session-title strong { color:#fd9a5c; font-weight:500; }
.session-steps { list-style:none; padding:0; margin:0; }
.session-steps li { display:flex; align-items:center; gap:14px; padding:18px 0; border-bottom:1px solid #ffffff0d; }
.session-steps li>span { display:grid; place-items:center; border:1px solid #406c93; border-radius:50%; width:28px; height:28px; color:#3ea4f5; flex:none; font-size:10px; }
.session-steps strong { display:block; font-size:13px; font-weight:500; }
.session-steps small { display:block; color:#aebcc8; font-size:10px; margin-top:6px; line-height:1.6; }
.session-steps b { font-size:10px; font-weight:500; color:#b6c7d5; margin-left:auto; white-space:nowrap; }
.ui-note { font-size:10px; color:#97a9b9; line-height:1.7; margin:20px 0 0; }
.memorize-demo { min-height:400px; display:grid; place-items:center; position:relative; isolation:isolate; }
.orbit { position:absolute; border:1px solid #5791c433; border-radius:50%; z-index:-1; aspect-ratio:1; max-width:100%; }
.orbit-one { width:350px; }
.orbit-two { width:265px; border-style:dashed; transform:rotate(30deg); }
.demo-flashcard { width:min(295px,85%); padding:30px 25px; background:linear-gradient(145deg,#234e74,#102333); border:1px solid #5d8db7; border-radius:12px; box-shadow:0 25px 75px #0005; transform:rotate(-3deg); }
.demo-flashcard>p { font-size:22px; font-weight:600; line-height:1.4; letter-spacing:-.5px; margin:28px 0; }
.demo-flashcard button { background:#dce9f5; color:#0e3252; border:0; border-radius:4px; padding:12px; width:100%; cursor:pointer; font-size:11px; font-weight:700; }
#flash-answer strong { font-size:21px; color:#fff; }
#flash-answer p { font-size:13px; line-height:1.7; color:#cadceb; }
.memory-label { position:absolute; bottom:5px; color:#3ea4f5; font-size:8px; letter-spacing:2px; }
.highlight-copy { font-size:14px; line-height:1.8; color:#b1c3d3; padding-left:18px; border-left:2px solid #fd6a18; }
.highlight-copy strong { color:#fff; font-weight:500; }
.filter-chips { display:flex; gap:6px; margin-top:25px; flex-wrap:wrap; }
.filter-chips span { font-size:9px; background:#185f9e2e; color:#b6d1e8; padding:8px 10px; border:1px solid #406c9366; border-radius:4px; }
.answer-row { display:flex; align-items:center; gap:15px; font-size:12px; margin:10px 0; padding:0 12px; border:1px solid #ffffff12; border-radius:5px; min-height:49px; }
.answer-row>span { color:#3ea4f5; font-size:9px; }
.answer-row p { color:#bac9d7; line-height:1.5; }
.answer-row b { margin-left:auto; font-weight:400; color:#90b1ce; }
.active-answer { border-color:#659dce; background:#185f9e22; }
.feedback-note { margin-top:25px; padding:18px 15px; border-left:2px solid #fd6a18; background:#00000066; }
.feedback-note strong { font-size:12px; font-weight:500; }
.feedback-note p { font-size:11px; line-height:1.7; color:#aebcc8; margin-bottom:0; }
.center-heading { text-align:center; max-width:710px; margin:0 auto 40px; }
.center-heading .section-lead { max-width:600px; margin:0 auto; }
.transfer-map { display:grid; grid-template-columns:1fr 1.15fr 1fr; align-items:center; gap:25px; padding:20px 0; }
.transfer-side { padding:24px 18px; border-top:1px solid #5791c444; border-bottom:1px solid #5791c444; text-align:center; }
.transfer-side>span { font-size:8px; letter-spacing:1.5px; color:#3ea4f5; }
.transfer-side strong { display:block; font-size:21px; margin:13px 0; font-weight:600; }
.transfer-side p { font-size:10px; color:#aebcc8; }
.transfer-core { text-align:center; border:1px solid #598cb8; background:radial-gradient(ellipse,#185f9e55,#081d2f); border-radius:50%; aspect-ratio:1; display:flex; flex-direction:column; justify-content:center; gap:14px; padding:22px; box-shadow:0 0 60px #185f9e22; }
.transfer-core>span { font-size:42px; color:#3ea4f5; line-height:1; }
.transfer-core strong { font-size:17px; font-weight:600; }
.transfer-core small { font-size:11px; color:#b5cde2; line-height:1.8; }
.center-note { font-size:11px; line-height:1.8; text-align:center; color:#99abbb; margin:25px auto 0; max-width:700px; }
.rev-monogram { display:flex; align-items:center; gap:12px; color:#3ea4f5; font-size:28px; font-weight:800; }
.rev-monogram>span { font-size:9px; font-weight:500; color:#b5cde2; }
.chat-message { font-size:13px; line-height:1.8; padding:19px; border-radius:8px; }
.user-message { margin:24px 0 18px 34px; background:#185f9e55; border:1px solid #598cb844; color:#deebf7; }
.rev-message { background:#000000aa; border:1px solid #406c9344; margin-right:16px; }
.rev-message strong { font-weight:600; }
.rev-message p { font-size:12px; color:#b0c2d1; }
.chat-tools { display:flex; flex-direction:column; gap:8px; margin-top:20px; }
.chat-tools span { color:#b9d5ed; font-size:10px; }
.chat-bottom { border-top:1px solid #598cb822; padding-top:20px; margin-top:24px; color:#a1b6c8; font-size:11px; display:flex; justify-content:space-between; }
.chat-bottom>span { color:#fd9a5c; }
.resource-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:0; border:1px solid #406c9355; border-radius:6px; overflow:hidden; }
.resource-grid article { padding:30px; border-right:1px solid #406c9344; border-bottom:1px solid #406c9344; }
.resource-grid article:nth-child(3n) { border-right:0; }
.resource-grid article:nth-last-child(-n+3) { border-bottom:0; }
.resource-grid article>span { color:#3ea4f5; font-size:8px; letter-spacing:1.4px; }
.resource-grid h3 { font-size:19px; font-weight:600; line-height:1.3; margin:22px 0 12px; letter-spacing:-.4px; }
