/* Direção visual 03: uma base contínua, símbolos e movimento por leitura. */
.police-symbols { position:absolute; width:0; height:0; overflow:hidden; pointer-events:none; }
.design-icon { width:24px; height:24px; fill:none; stroke:currentColor; stroke-width:1.5; stroke-linecap:round; stroke-linejoin:round; flex:none; }
.policial .eyebrow { display:flex; align-items:center; gap:12px; }
.policial .eyebrow>.section-icon { display:grid; place-items:center; flex:none; width:36px; height:36px; border:1px solid #6d99c04d; border-radius:10px; background:#185f9e12; color:#b6d1e8; box-shadow:none; }
.section-icon .design-icon { width:20px; height:20px; }
.center-heading .eyebrow { justify-content:center; }
.policial main>.vt-frame>section { position:relative; }
.policial main>.vt-frame>section:not(.b-police-hero) { padding-top:100px; }
.section-connector { position:absolute; top:0; left:50%; transform:translateX(-50%); display:flex; align-items:center; justify-content:center; width:min(450px,65%); height:46px; pointer-events:none; }
.connector-line { height:1px; flex:1; background:linear-gradient(90deg,transparent,#659dce66); transform-origin:right center; }
.connector-line:last-child { background:linear-gradient(90deg,#659dce66,transparent); transform-origin:left center; }
.connector-node { width:34px; height:34px; border:1px solid #6d99c044; border-radius:50%; background:var(--police-canvas); color:#82acd1; display:grid; place-items:center; flex:none; margin:0 12px; box-shadow:0 0 24px #185f9e12; }
.connector-node .design-icon { width:15px; height:15px; }
.page-view .section-connector { top:-1px; }
.policial.page-view .vt-frame { overflow:visible; background:var(--police-canvas); }
.policial.page-view main { background:var(--police-canvas); }
.resource-icon { width:45px; height:45px; display:grid; place-items:center; background:#185f9e1a; border:1px solid #659dce44; border-radius:12px; color:#b6d1e8; margin-bottom:22px; }
.resource-icon .design-icon { width:25px; height:25px; }
.resource-grid article { position:relative; background:transparent; transition:background 220ms ease; }
.resource-grid article:hover { background:#185f9e12; }
.policial .friction>.friction-symbol { display:flex; flex-direction:column; align-items:center; gap:7px; padding-top:1px; min-width:30px; }
.friction-symbol .design-icon { width:21px; height:21px; color:#3ea4f5; }
.friction-symbol small { font-size:8px; letter-spacing:1px; color:#85a2bc; }
.guarantee-grid article { position:relative; }
.guarantee-icon { position:absolute; right:30px; top:32px; width:50px; height:50px; border:1px solid #659dce44; border-radius:14px; display:grid; place-items:center; color:#3ea4f5; background:#185f9e12; }
.guarantee-icon .design-icon { width:28px; height:28px; }
.price-tag { display:flex; align-items:center; gap:10px; line-height:1.6; }
.price-tag .design-icon { width:19px; height:19px; }
.price-guarantee { display:flex; align-items:center; justify-content:center; gap:8px; }
.price-guarantee .design-icon { width:17px; height:17px; }
.method-card,.ui-panel,.guarantee-grid article,.bonus-card { background:var(--police-surface); border-color:var(--police-line); }
.method-card,.bonus-card { transition:border-color 220ms ease,box-shadow 220ms ease; }
.method-card:hover,.bonus-card:hover { border-color:#659dce77; box-shadow:0 15px 45px #0002; }
.method-card .card-top svg { transition:color 220ms ease,transform 220ms ease; }
.method-card:hover .card-top svg { color:#fd9a5c; transform:translateY(-3px); }
.police-faq summary>span { transition:transform 200ms ease; }
.reading-progress { position:fixed; top:0; left:0; right:0; height:3px; z-index:30; pointer-events:none; }
.reading-progress>span { display:block; width:100%; height:100%; background:linear-gradient(90deg,#267bc5 0%,#8eb7db 70%,#fd6a18); transform:scaleX(0); transform-origin:left; }
.motion-enabled .connector-play .connector-line { animation:police-connect 950ms cubic-bezier(.16,1,.3,1) both; }
.motion-enabled .connector-play .connector-node { animation:police-node 1200ms ease-out both; }
.motion-enabled .diagram-play .bars i { animation:police-chart 800ms cubic-bezier(.16,1,.3,1) both; transform-origin:bottom; }
.motion-enabled .diagram-play .bars i:nth-child(2n) { animation-delay:80ms; }
.motion-enabled .diagram-play .bars i:nth-child(3n) { animation-delay:160ms; }
@keyframes police-connect { from { opacity:0; transform:scaleX(.15); } to { opacity:1; transform:scaleX(1); } }
@keyframes police-node { 0% { opacity:0; transform:scale(.85); box-shadow:0 0 0 #267bc500; } 55% { opacity:1; transform:scale(1); box-shadow:0 0 25px #267bc533; } 100% { opacity:1; transform:scale(1); box-shadow:0 0 24px #185f9e12; } }
@keyframes police-chart { from { transform:scaleY(.2); opacity:.3; } to { transform:scaleY(1); opacity:1; } }
