/* Revolução — cores primitivas e semânticas */
:root {
  /* Primitivos: roxo da marca */
  --rev-purple-50: #F8F2FB;
  --rev-purple-100: #EEDCF5;
  --rev-purple-200: #D9B6E8;
  --rev-purple-300: #C48EDB;
  --rev-purple-400: #AE65CE;
  --rev-purple-500: #9126C5;
  --rev-purple-600: #72189E;
  --rev-purple-700: #551277;
  --rev-purple-800: #3C0E52;
  --rev-purple-900: #25082F;
  --rev-purple-950: #10071D;

  /* Primitivos: laranja da marca */
  --rev-orange-50: #FFF6F0;
  --rev-orange-100: #FFE8D8;
  --rev-orange-200: #FEBB8D;
  --rev-orange-300: #FF9A5C;
  --rev-orange-400: #FD7D32;
  --rev-orange-500: #FD6A18;
  --rev-orange-600: #E85A00;
  --rev-orange-700: #C94700;
  --rev-orange-800: #9C3500;
  --rev-orange-900: #6B2300;

  /* Primitivos: ciano (foco, progresso, IA em contexto) */
