  --rev-cyan-200: #A5F3FC;
  --rev-cyan-300: #67E8F9;
  --rev-cyan-400: #43E6EE;
  --rev-cyan-500: #22D3EE;
  --rev-cyan-600: #0891B2;
  --rev-cyan-700: #0E7490;

  /* Primitivos: azul de destaque */
  --rev-blue-100: #D9EEFF;
  --rev-blue-300: #7CC4F5;
  --rev-blue-500: #158CE6;
  --rev-blue-700: #0E5D9D;

  /* Primitivos: magenta (IA e celebração) */
  --rev-magenta-400: #BB52ED;
  --rev-magenta-500: #A73FD6;
  --rev-magenta-700: #74259A;

  /* Primitivos: neutros */
  --rev-white: #FFFFFF;
  --rev-neutral-25: #FAFAFA;
  --rev-neutral-50: #F7F7FA;
  --rev-neutral-100: #F1F1F4;
  --rev-neutral-200: #E4E4E7;
