  --rev-neutral-500: #71717A;
  --rev-neutral-600: #52525B;
  --rev-neutral-700: #3F3F46;
  --rev-neutral-800: #27272A;
  --rev-neutral-900: #18181B;

  /* Primitivos: superfícies especiais */
  --rev-surface-warm: #FFF1E7;
  --rev-surface-dark-raised: #3D0E55;
  --rev-surface-dark-subtle: #1D092C;
  --rev-surface-dark-border: #4A2973;

  /* Primitivos: feedback */
  --rev-success: #168A5B;
  --rev-warning: #A86500;
  --rev-danger: #C9343A;
  --rev-info: #158CE6;
  --rev-success-bg: #E8F6F0;
  --rev-warning-bg: #FCF3E3;
  --rev-danger-bg: #FBEAEA;
  --rev-info-bg: #EFF8FF;

  /* Semântico: light (padrão) */
  --rev-bg-canvas: #F7F7FA;
  --rev-bg-gradient: linear-gradient(168deg, #F8F5FC 0%, #F1EAF9 48%, #E9DFF5 100%);
  --rev-bg-surface: #FFFFFF;
  --rev-bg-subtle: #F1F1F4;
  --rev-bg-warm: #FFF1E7;
  --rev-bg-brand: #3C0E52;
  --rev-text-primary: #10071D;
  --rev-text-secondary: #52525B;
  --rev-text-muted: #71717A;
  --rev-text-inverse: #FFFFFF;
  --rev-text-on-accent: #10071D;
  --rev-text-brand: #3C0E52;
  --rev-border-default: #D4D4D8;
  --rev-border-strong: #A1A1AA;
  --rev-border-focus: #43E6EE;
  --rev-action-primary: #3C0E52;
  --rev-action-primary-hover: #551277;
