.pv-section--light .pv-origem__lista li, .pv-section--soft .pv-origem__lista li { background: #F7F7FA; border-color: #E4E4E7; color: #3F3F46; }
.pv-section--light .pv-origem__lista strong, .pv-section--soft .pv-origem__lista strong { color: #10071D; }

.pv-section--dark .pv-faq, .pv-section--deep .pv-faq { background: rgba(255, 255, 255, 0.04); border-color: #33184F; }
.pv-section--dark .pv-faq summary, .pv-section--deep .pv-faq summary { color: #FAFAFA; }
