/* ═══ "Problema de caos": ferramentas com setinhas (ícones de linha azuis, parados e centralizados) ═══ */
.pv-caos { align-self: stretch; width: 100%; display: flex; align-items: flex-start; justify-content: center; gap: 6px; margin: 6px 0 2px; }
.pv-caos__item { flex: 1 1 0; min-width: 0; max-width: 112px; display: flex; flex-direction: column; align-items: center; gap: 9px; }
.pv-caos__ico { width: 60px; height: 60px; border-radius: 1rem; border: 1.5px solid #7BBBF1; background: #FFFFFF; color: #158CE6; display: flex; align-items: center; justify-content: center; box-shadow: 0 6px 16px rgba(21, 140, 230, 0.12); }
.pv-caos__ico svg .fundo { fill: #FFFFFF; stroke: none; }
.pv-caos__nome { font-size: 0.78rem; font-weight: 700; line-height: 1.25; text-align: center; color: #3F3F46; text-wrap: balance; }
.pv-caos__seta { flex: 0 0 22px; margin-top: 20px; color: #2F9AF5; display: flex; justify-content: center; }
.pv-section--dark .pv-caos__ico, .pv-section--deep .pv-caos__ico { background: #0F1B2D; border-color: rgba(108, 192, 246, 0.45); color: #6CC0F6; box-shadow: none; }
