.pv-section--dark .pv-caos__nome, .pv-section--deep .pv-caos__nome { color: #C4C1CB; }
.pv-section--dark .pv-caos__seta, .pv-section--deep .pv-caos__seta { color: #6CC0F6; }
@media (max-width: 720px) {
