/* FAQ: mesmo layout da página de resgate, isolado nesta lista. */
      .pv-faq-resgate { max-width: 820px; margin: 0 auto; width: 100%; display: flex; flex-direction: column; gap: 10px; counter-reset: duvida; }
      .pv-faq-resgate details { background: #FFFFFF; border: 1px solid #E4E4E7; border-radius: 10px; padding: 0 18px; counter-increment: duvida; transition: border-color .18s, box-shadow .18s; }
      .pv-faq-resgate details[open] { border-color: #FD6A18; box-shadow: 0 2px 14px rgba(253,106,24,0.1); }
      /* Número à esquerda e seta à direita (Kleber, 23/10): o número dá a dimensão
         da lista e a seta avisa que a pergunta abre. O marcador nativo sai, senão
         ficam dois indicadores dizendo a mesma coisa. */
      .pv-faq-resgate summary { cursor: pointer; padding: 14px 0; font-weight: 700; color: #10071D;
        display: flex; align-items: center; gap: 12px; list-style: none; }
      .pv-faq-resgate summary::-webkit-details-marker { display: none; }
      .pv-faq-resgate summary::before { content: counter(duvida, decimal-leading-zero);
        flex: none; min-width: 26px; height: 26px; border-radius: 7px;
        display: inline-flex; align-items: center; justify-content: center;
        background: #FFF1E7; color: #C94700; font-size: .78rem; font-weight: 700;
        font-variant-numeric: tabular-nums; transition: background .18s, color .18s; }
      .pv-faq-resgate details[open] summary::before { background: #FD6A18; color: #FFFFFF; }
      .pv-faq-resgate summary::after { content: ""; flex: none; margin-left: auto; width: 9px; height: 9px;
        border-right: 2px solid #A1A1AA; border-bottom: 2px solid #A1A1AA; border-radius: 1px;
        transform: rotate(45deg) translateY(-2px); transition: transform .2s, border-color .18s; }
      .pv-faq-resgate details[open] summary::after { transform: rotate(-135deg) translateY(-2px); border-color: #FD6A18; }
      .pv-faq-resgate p { margin: 0 0 16px; color: #52525B; line-height: 1.6; padding-left: 38px; }
      @media (prefers-reduced-motion: reduce) { .pv-faq-resgate summary::after { transition: none } }
      @media (max-width: 560px) { .pv-faq-resgate p { padding-left: 0 } }

.pv-faq-resgate p { line-height: 1.7; }

