.pv-mapa-revisao a { color: #10071D; }
.pv-mapa-revisao li a { display: flex; gap: 8px; align-items: baseline; line-height: 1.45; padding: 9px 0; text-decoration: none; border-bottom: 1px solid #eeded2; }
.pv-mapa-revisao li a:hover { color: #C94700; }
.pv-mapa-revisao li span { font-weight: 800; color: #C94700; }
.pv-mapa-revisao small { margin-left: auto; color: #766b72; font-size: .72rem; }
.pv-ver-sem-notas { display: inline-block; margin-top: 4px; font-size: .85rem; }
.pv-rotulo-revisao {
  box-sizing: border-box; padding: 12px 24px; background: #24132e;
  color: #FFFFFF; font-size: .82rem; font-weight: 700; letter-spacing: .02em;
}
.pv-nota-revisao {
  box-sizing: border-box; width: calc(100% - 48px); max-width: 1080px;
  margin: 20px auto; padding: 18px 22px; border-left: 4px solid #FD6A18;
  background: #FFF1E7; color: #10071D; border-radius: 0 8px 8px 0;
}
.pv-nota-revisao strong { color: #C94700; text-transform: uppercase; font-size: .75rem; }
.pv-nota-revisao p { margin: 7px 0 0; line-height: 1.6; font-size: .92rem; }
.pv-espacos-revisao { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 18px; }
.pv-espaco-revisao { box-sizing: border-box; min-height: 150px; padding: 24px; border: 1px dashed #C94700; border-radius: 12px; background: #FFFAF5; color: #10071D; }
.pv-espaco-revisao p { font-size: .9rem; color: #756b72; line-height: 1.6; }
.pv-resposta-pendente { color: #C94700 !important; }
@media (max-width: 680px) {
  .pv-mapa-revisao ol, .pv-espacos-revisao { grid-template-columns: minmax(0,1fr); }
  .pv-nota-revisao { width: calc(100% - 36px); padding: 16px; }
  .pv-mapa-revisao small { max-width: 80px; }
}

/* O brilho decorativo permanece atrás de todo o texto do topo. */
