#bloco-01 > section > div > span[aria-hidden="true"] { z-index: 0; }
#bloco-01 h1,
#bloco-01 .pv-hero-subhead {
  position: relative;
  z-index: 1;
}

/* Modelo local de prova social em vídeo, sem alegações de aprovação. */
.pv-prova-video__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;width:100%}
.pv-prova-video__card{min-width:0;overflow:hidden;border:1px solid #E4E4E7;border-radius:16px;background:#fff}
.pv-prova-video__capa{position:relative;aspect-ratio:16/9;overflow:hidden;background:#170E23}
.pv-prova-video__capa img{display:block;width:100%;height:100%;object-fit:cover}
.pv-prova-video__play{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);display:grid;place-items:center;width:56px;height:48px;border-radius:8px;background:#FD6A18;border-bottom:4px solid #C94700;color:#fff;font-size:22px;box-shadow:0 8px 26px #FD6A1866}
.pv-prova-video__selo{position:absolute;top:12px;left:12px;padding:5px 9px;background:#fff;color:#27202F;border-radius:6px;font-size:12px;font-weight:700}
.pv-prova-video__texto{padding:20px}.pv-prova-video__texto h3{margin:0 0 8px;font-size:18px}.pv-prova-video__texto p{margin:0;color:#62606A;font-size:14px}
.pv-prova-video__aviso{font-size:14px;line-height:1.6;color:#62606A;max-width:640px;margin:14px auto 0;text-align:center}
