#jornada .pv-corpo p{font-family:var(--rev-font-body,inherit);font-size:1.0625rem;font-weight:400;line-height:1.7;color:#3F3F46;text-align:left;text-wrap:pretty;margin:0}

/* Aulas: mesma leitura e destaques cinza da Jornada. */
