.pv-bloco-estrutura .pv-corpo p,.pv-bloco-estrutura .pv-texto-longo p,.pv-bloco-estrutura .pv-prose p,.pv-bloco-estrutura .pv-head>p,.pv-bloco-estrutura .pv-tela-intro,#simulados>div>div>p{
 font-family:var(--rev-font-body,inherit)!important;font-size:1.0625rem!important;font-weight:400!important;line-height:1.7!important;letter-spacing:normal!important;text-align:left!important;text-wrap:pretty;color:#3F3F46!important
}
.pv-bloco-estrutura .pv-head>p,.pv-bloco-estrutura .pv-tela-intro,#simulados>div>div>p{width:100%;max-width:820px!important;margin-left:auto!important;margin-right:auto!important}
.pv-section--dark .pv-corpo p,.pv-section--deep .pv-corpo p,.pv-section--dark .pv-head>p,.pv-section--deep .pv-head>p{color:#C4C1CB!important}

