#para-quem .pv-grid>div:last-child>div strong{color:#C93442!important}

/* Comparação clara, seguida da oferta ampla com leitura em duas colunas. */
#comparacao-plataformas .pv-comparativo>div{box-sizing:border-box;min-width:0}
#comparacao-plataformas .pv-comparativo>div:not(:last-child){background:#FFFFFF!important;border:1px solid #E4E4E7!important}
#comparacao-plataformas .pv-comparativo>div:not(:last-child)>span,#comparacao-plataformas .pv-comparativo>div:not(:last-child)>strong{color:#3F3F46!important}
#comparacao-plataformas .pv-la-aqui__la{background:#F1F1F3;border-color:#E4E4E7;color:#3F3F46}
#comparacao-plataformas .pv-la-aqui__aqui{background:#EDF9F2;border-color:#B9DFCB;color:#3F3F46}
#comparacao-plataformas .pv-la-aqui__aqui b{color:#127A4A}
#comparacao-plataformas .pv-la-aqui__la b{color:#C93442}
.pv-oferta-ampla{width:100%;min-width:0}
#oferta .pv-plano--unico{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(300px,.85fr);gap:40px;padding:28px;align-items:center}
.pv-plano__conteudo{min-width:0}
