#oferta .pv-plano__preco{box-sizing:border-box;min-width:0;margin:0;padding:32px 24px;background:#F7F7FA;border-radius:16px;display:flex;flex-direction:column;gap:20px}
#oferta .pv-plano__numero{font-size:clamp(2.5rem,4.5vw,3.5rem)}
