}

/* Oferta: arte à esquerda; benefícios e preço juntos à direita. */
#oferta .pv-plano--unico{grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:start}
#oferta .pv-plano__conteudo{display:flex;flex-direction:column;min-width:0}
