}

/* Depoimentos escritos: marcadores de revisão, sem pessoas ou resultados inventados. */
.pv-depoimentos-texto{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;width:100%}
.pv-depoimento-texto{box-sizing:border-box;min-width:0;padding:28px;border:1px solid #E4E4E7;border-radius:16px;background:#FFFFFF;display:flex;flex-direction:column;gap:24px}
.pv-depoimento-texto__selo{align-self:flex-start;background:#F7F7FA;border-radius:6px;padding:5px 9px;font-size:12px;font-weight:700;color:#62626B}
.pv-depoimento-texto blockquote{margin:0;flex:1}
.pv-depoimento-texto__aspas{display:block;color:#FD6A18;font-size:52px;line-height:1;font-weight:900}
.pv-depoimento-texto blockquote p{margin:8px 0 0;font-size:17px;line-height:1.7;color:#3F3F46;text-align:left}
.pv-depoimento-texto__pessoa{display:flex;flex-direction:column;gap:6px;border-top:1px solid #E4E4E7;padding-top:18px}
.pv-depoimento-texto__pessoa strong{font-size:15px;color:#18181B}
.pv-depoimento-texto__pessoa>span{font-size:14px;line-height:1.5;color:#62626B}
@media(max-width:700px){.pv-depoimentos-texto{grid-template-columns:1fr;gap:20px}}

/* No celular, três concursos e expansão acessível por botão. */
.pv-concursos-expandir{display:none}
@media(max-width:700px){
 #concursos .pv-concursos-grade:not(.pv-concursos-grade--aberta)>.pv-concurso-card:nth-child(n+4){display:none}
 #concursos .pv-concursos-expandir{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:48px;margin:24px auto 0;padding:12px 22px;background:#FD6A18;color:#FFFFFF;border:0;border-bottom:3px solid #C94700;border-radius:8px;font:700 1rem Mundial,sans-serif;cursor:pointer}
}

/* Relatos de exemplo: três por vez no desktop e expansão no celular. */
@media(min-width:701px){
 .pv-depoimentos-texto{grid-template-columns:none;grid-auto-flow:column;grid-auto-columns:calc((100% - 48px)/3);overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;padding-bottom:2px}
 .pv-depoimentos-texto::-webkit-scrollbar{display:none}
 .pv-depoimento-texto{scroll-snap-align:start}
}
.pv-depoimentos-controles{display:flex;justify-content:center;gap:12px;margin-top:24px}
.pv-depoimentos-seta,.pv-depoimentos-mais{box-sizing:border-box;border:0;border-bottom:3px solid #C94700;border-radius:8px;background:#FD6A18;color:#FFFFFF;font:700 1rem Mundial,sans-serif;cursor:pointer}
.pv-depoimentos-seta{width:48px;height:48px;font-size:24px}
.pv-depoimentos-seta:disabled{opacity:.4;cursor:default}
.pv-depoimentos-mais{display:none;padding:12px 24px;min-height:48px;margin:24px auto 0}
.pv-depoimentos-seta:focus-visible,.pv-depoimentos-mais:focus-visible{outline:3px solid #9126C5;outline-offset:4px}
@media(max-width:700px){
 .pv-depoimentos-texto:not(.pv-depoimentos-texto--aberta)>.pv-depoimento-texto:nth-child(n+4){display:none}
 .pv-depoimentos-controles{display:none}
 .pv-depoimentos-mais{display:block}
}

/* Desktop: apenas uma seta à direita. */
.pv-depoimentos-carrossel{position:relative;width:100%;min-width:0}
#pv-depoimentos-anterior{display:none}
