 .pv-depoimentos-carrossel .pv-depoimentos-controles{position:absolute;right:-20px;top:50%;transform:translateY(-50%);margin:0;z-index:2}
 .pv-depoimentos-mais{display:none!important}
}
@media(max-width:700px){.pv-depoimentos-carrossel .pv-depoimentos-controles{display:none!important}}

/* Setas discretas nas duas laterais do carrossel. */
.pv-depoimentos-seta{display:flex;align-items:center;justify-content:center;background:transparent;color:#62626B;border:0;border-radius:8px;box-shadow:none}
.pv-depoimentos-seta:hover:not(:disabled){color:#10071D;background:rgba(16,7,29,.04)}
.pv-depoimentos-seta:disabled{opacity:.3}
