 .pv-depoimentos-carrossel{box-sizing:border-box;padding:0 40px}
 .pv-depoimentos-carrossel .pv-depoimentos-controles{left:0;right:0;top:50%;justify-content:space-between;pointer-events:none}
 .pv-depoimentos-seta{width:36px;height:48px;pointer-events:auto}
}

/* Preço anterior e parcelas com espaçamento compacto. */
#oferta .pv-plano__preco{gap:8px}
#oferta .pv-plano__preco-anterior{display:block;margin:8px 0 0;font-size:1.15rem;font-weight:600;line-height:1.3;color:#71717A;text-decoration-thickness:2px}
