/* Garantia no formato de lista numerada, cartões brancos sobre a faixa cinza. */
.pv-garantia-lista{position:relative;margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:18px}
.pv-garantia-lista__linha{position:absolute;left:17px;top:30px;bottom:30px;width:1px;background:linear-gradient(180deg,rgba(18,122,74,0.45),rgba(18,122,74,0.08));z-index:0}
.pv-garantia-lista>li{position:relative;z-index:1;display:flex;gap:18px;align-items:flex-start;background:#FFFFFF;border:1px solid #E4E4E7;border-radius:16px;padding:24px 26px}
.pv-garantia-lista__num{flex:none;width:34px;height:34px;border-radius:999rem;background:#EDF9F2;border:1.5px solid #127A4A;color:#127A4A;display:flex;align-items:center;justify-content:center;font-size:0.95rem;font-weight:800}
