@media(max-width:620px){.pv-garantia-lista>li{padding:20px 18px;gap:14px}.pv-garantia-lista__linha{left:15px}.pv-garantia-lista__num{width:30px;height:30px;font-size:0.85rem}}

/* A oferta perdeu o título; sem ele o respiro entre dois parágrafos virava buraco. */
