/* Garantias: topo só com título e texto, sem fundo roxo e sem o Rév (27/10) */
.pv-garantia-topo{box-sizing:border-box;display:block;max-width:1080px;width:100%;margin:0 auto;padding:0;background:none;border:0;border-radius:0;box-shadow:none;overflow:visible;text-align:center}
.pv-garantia-topo__texto{padding:0;text-align:center}
.pv-garantia-topo .pv-title{margin:0;color:#10071D;text-align:center}
.pv-garantia-topo p{margin:14px auto 0;max-width:none;font-size:1.05rem;line-height:1.6;color:#52525B;text-wrap:pretty}
.pv-garantia-topo p strong{color:#168A5B}

/* Preço escondido atrás de um clique no card da oferta (27/10) */
.pv-plano__ver{display:block;width:100%;margin-top:14px;padding:0.95rem 0;background:#FD6A18;color:#FFFFFF;font:inherit;font-weight:800;font-size:1rem;border:0;border-radius:8px;box-shadow:0 3px 0 #C94700;cursor:pointer}
.pv-plano__ver:hover{filter:brightness(1.08)}
