/* Bônus RÉV Coins abaixo do botão da oferta (27/10) */
.pv-plano__bonus{margin-top:16px;padding:14px 16px;text-align:left;background:#FFFFFF;border:1px dashed #C9B8D9;border-radius:12px}
.pv-plano__bonus-selo{display:inline-block;padding:3px 9px;margin-bottom:8px;background:#FD6A18;color:#FFFFFF;font-size:.68rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase;border-radius:999rem}
