.pv-plano__bonus p{margin:4px 0 0;font-size:.875rem;line-height:1.55;color:#52525B}

/* Rodapé igual ao da página de resgate (27/10) */
.rf-rodape{background:#10071D;border-top:1px solid #4A2973;padding:16px 24px 12px;color:#c8bad4;text-align:center}
.rf-rodape-linha{max-width:1120px;margin:auto;display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}
