/* Play grande sobre o vídeo de abertura, igual ao da página de resgate (27/10) */
.pv-play{position:absolute;inset:2px;display:flex;align-items:center;justify-content:center;border:0;padding:0;background:transparent;cursor:pointer;border-radius:calc(1.25rem - 2px)}
.pv-play[hidden]{display:none}
.pv-play::before{content:"";position:absolute;width:170px;height:170px;border-radius:999rem;background:rgba(253,106,24,0.20);animation:pvPulse 2.6s ease-in-out infinite}
.pv-play::after{content:"";position:absolute;width:130px;height:130px;border-radius:999rem;background:rgba(255,154,77,0.14)}
.pv-play-bola{position:relative;width:92px;height:92px;border-radius:999rem;background:linear-gradient(135deg,#FF9A4D 0%,#FD6A18 55%,#C94700 130%);display:flex;align-items:center;justify-content:center;box-shadow:0 12px 40px rgba(253,106,24,0.5)}
.pv-play-dica{position:absolute;bottom:16px;left:20px;font-size:.875rem;color:#C9C4D2;pointer-events:none;text-shadow:0 1px 6px #0009}
#video-de-abertura:has(.pv-play:not([hidden])) video::-webkit-media-controls{display:none}
#video-de-abertura:has(.pv-play:not([hidden])) video::-webkit-media-controls-enclosure{display:none}
@keyframes pvPulse{0%,100%{transform:scale(1);opacity:.85}50%{transform:scale(1.12);opacity:.45}}
@media(prefers-reduced-motion:reduce){.pv-play::before{animation:none}}
@media(max-width:640px){.pv-play-bola{width:66px;height:66px}.pv-play-bola svg{width:19px;height:22px}.pv-play::before{width:118px;height:118px}.pv-play::after{width:92px;height:92px}.pv-play-dica{bottom:11px;left:13px;font-size:.78rem}}


/* Suporte: título centralizado, texto e e-mail (27/10) */
.pv-garantia-suporte{align-items:center;text-align:center;gap:10px;padding:28px 26px}
.pv-garantia-suporte h3{margin:0;font-size:1.5rem;font-weight:800;line-height:1.2;color:#10071D}
.pv-garantia-suporte p{max-width:none;margin:0 auto}
.pv-garantia-suporte a{font-size:1.0625rem;font-weight:800;color:#3C0E52;text-decoration:underline;text-underline-offset:3px}
.pv-garantia-suporte a:hover{color:#FD6A18}

/* O rodapé deve aparecer por inteiro, mesmo no fim da rolagem (igual ao resgate). */
.rf-rodape .pv-reveal{opacity:1!important;transform:none!important}

/* Fechamento no formato dos cards com imagem: texto à esquerda, raposa à direita (27/10) */
.pv-fechamento-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;align-items:stretch;max-width:1020px;width:100%;margin:0 auto}
.pv-fechamento-card{background:#17121F;border:1px solid rgba(255,255,255,0.08);border-radius:1.4rem;padding:30px 28px;display:flex;flex-direction:column;justify-content:center;gap:14px;text-align:left}
.pv-fechamento-card p{margin:0;font-size:0.95rem;line-height:1.65;color:#9B93A2}
.pv-fechamento-card .pv-fechamento-meio{margin-top:4px;padding-top:14px;border-top:1px dashed rgba(255,255,255,0.14);color:#C4C1CB}
.pv-fechamento-card .pv-forte{color:#FAFAFA;font-weight:700}
.pv-pilar-foto{position:relative;border-radius:1.4rem;overflow:hidden;min-height:300px;box-shadow:0 0 60px 6px rgba(67,230,238,0.28),0 0 90px 14px rgba(145,38,197,0.24)}
.pv-pilar-foto img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
@media(max-width:760px){.pv-fechamento-grid{grid-template-columns:1fr;gap:20px}.pv-pilar-foto{min-height:240px;aspect-ratio:4/3}}

/* Rév 2D fechando a página, igual ao da página de resgate (27/10) */
.pv-rev-fim{display:block;width:170px;height:auto;margin:10px auto -48px;pointer-events:none;position:relative;z-index:1}
@media(max-width:760px){.pv-rev-fim{width:128px;margin:14px auto -40px}}

