*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  font-family:'Mundial','Open Sans',ui-rounded,'Segoe UI',system-ui,-apple-system,sans-serif;
  background:#0C0514;color:#FAFAFA;line-height:1.6;-webkit-font-smoothing:antialiased;
}
img{display:block;max-width:100%}
button{font-family:inherit;cursor:pointer;border:none}
:focus-visible{outline:2px solid #BB52ED;outline-offset:3px;border-radius:6px}
@media (prefers-reduced-motion: reduce){*{transition:none !important;animation:none !important}}

.logo{height:26px;width:auto;margin:0 auto 22px;display:block}

/* ═══ Fileira de áreas (cards no mesmo padrão da página de Carreiras do blog) ═══ */
.areas{max-width:1100px;margin:0 auto;padding:0 22px 54px;text-align:center}
.areas p{font-size:.82rem;color:#8b8194;margin-bottom:16px}
.areas-fileira{display:grid;grid-template-columns:repeat(4,1fr);gap:1.1rem;text-align:left}
.carr-card{position:relative;aspect-ratio:1/1.28;overflow:hidden;border-radius:1rem;display:block;background:#10071D;box-shadow:0 6px 18px rgba(0,0,0,.35);text-decoration:none}
.carr-foto{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center top;transition:transform .6s}
.carr-card:hover .carr-foto{transform:scale(1.06)}
.carr-veu{position:absolute;inset:0;background:linear-gradient(to top,rgba(7,3,15,.93) 0%,rgba(7,3,15,.84) 20%,rgba(7,3,15,.6) 45%,rgba(7,3,15,.28) 72%,rgba(7,3,15,.12) 100%)}
.carr-conteudo{position:absolute;inset:0;display:flex;flex-direction:column;padding:1rem;text-align:left}
.carr-cabeca{display:flex;align-items:center;gap:.5rem;margin-bottom:.4rem}
.carr-ico{display:grid;place-items:center;width:1.8rem;height:1.8rem;border-radius:.45rem;background:linear-gradient(135deg,#FF9A4D,#FD6A18);color:#FFF;box-shadow:0 3px 10px rgba(253,106,24,.45);flex:none}
.carr-ico svg{width:1rem;height:1rem}
.carr-txt{margin-top:auto}
.carr-nome{display:block;font-size:1.1rem;font-weight:800;color:#FFF;line-height:1.2}
.carr-desc{display:block;margin-top:.35rem;font-size:.76rem;line-height:1.45;color:rgba(255,255,255,.9)}
.carr-saiba{display:inline-flex;align-items:center;gap:.35rem;margin-top:.75rem;padding:.4rem .9rem;border-radius:999px;border:1px solid rgba(255,255,255,.55);background:rgba(255,255,255,.12);color:#FFF;font-weight:700;font-size:.76rem;backdrop-filter:blur(4px);transition:background .18s,border-color .18s}
.carr-card:hover .carr-saiba{background:#FD6A18;border-color:#FD6A18}
@media (max-width:860px){.areas-fileira{grid-template-columns:repeat(2,1fr)}}

/* ═══ Depoimento ═══ */
.prova{max-width:640px;margin:0 auto;padding:0 22px 60px;text-align:center}
.prova blockquote{font-size:.98rem;color:#E4D9F5;line-height:1.75;max-width:46ch;margin:0 auto}
.prova blockquote strong{color:#FAFAFA}
.prova .quem{margin-top:14px;font-size:.78rem;color:#8b8194}

.rodape{border-top:1px solid rgba(255,255,255,.1);padding:22px;text-align:center;font-size:.74rem;color:#8b8194}

/* ═══ Mobile: o computador é o protagonista, sem cards soltos colidindo ═══ */
@media (max-width:700px){
  section div[style*="height:500px"] > div[style*="position:absolute"]:not([data-keep]){display:none}
  section img[alt="Rév"]{width:200px !important}
  [data-keep] div[style*="grid-template-columns"] > span{min-width:0;overflow-wrap:break-word}
  .carr-card{aspect-ratio:1/1.55}
  .carr-desc{font-size:.7rem}
}

/* ==========================================================================
   Black Friday Revolução — funil de captura (Vitrine, preview interno)
   Modelado das referências enviadas pelo Kleber em 16/09: topo com logotipo
   e formulário, painel "quem entra na lista", página "quase lá" com passos
   neon e página de obrigado com a raposa recortada.
   ========================================================================== */

@font-face { font-family: "Mundial"; src: url("/k/fontes/mundial-regular.woff2") format("woff2"); font-weight: 400; font-style: normal; font-display: swap; }
@font-face { font-family: "Mundial"; src: url("/k/fontes/mundial-demibold.woff2") format("woff2"); font-weight: 500 600; font-style: normal; font-display: swap; }
@font-face { font-family: "Mundial"; src: url("/k/fontes/mundial-bold.woff2") format("woff2"); font-weight: 700 800; font-style: normal; font-display: swap; }
@font-face { font-family: "Mundial"; src: url("/k/fontes/mundial-black.woff2") format("woff2"); font-weight: 900; font-style: normal; font-display: swap; }

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: "Mundial", "Poppins", system-ui, sans-serif;
  color: #FFFFFF;
  background: #0A0410;
  -webkit-font-smoothing: antialiased;
}

/* Fundo roxo profundo com brilhos magenta e pontilhado de meio-tom */
.bf-fundo {
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(52rem 32rem at 85% 12%, rgba(145, 38, 197, 0.35), transparent 62%),
    radial-gradient(40rem 28rem at 8% 88%, rgba(253, 106, 24, 0.14), transparent 60%),
    linear-gradient(158deg, #1C0A2E 0%, #12061F 55%, #0C0514 100%);
}
.bf-fundo::before {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background-image: radial-gradient(rgba(255, 255, 255, 0.10) 1px, transparent 1.4px);
  background-size: 14px 14px;
  mask-image: radial-gradient(46rem 30rem at 88% 8%, #000 0%, transparent 70%);
  -webkit-mask-image: radial-gradient(46rem 30rem at 88% 8%, #000 0%, transparent 70%);
}
.bf-wrap { position: relative; max-width: 76rem; margin: 0 auto; padding: 0 1.5rem; }

/* ---------- Logotipo Black Friday ---------- */
.bf-logo { display: flex; flex-direction: column; line-height: 0.92; }
.bf-logo .bf-black { font-family: "Mundial", sans-serif; font-weight: 900; font-size: clamp(3rem, 7vw, 5.2rem); letter-spacing: 0.01em; color: #FFFFFF; }
.bf-logo .bf-friday {
  font-family: "Mundial", sans-serif; font-weight: 900; font-size: clamp(3rem, 7vw, 5.2rem); letter-spacing: 0.01em;
  background: linear-gradient(92deg, #FD6A18 0%, #BB52ED 55%, #43E6EE 115%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.bf-logo .bf-marca { margin-top: 0.9rem; font-family: "Mundial", sans-serif; font-weight: 500; font-size: clamp(0.85rem, 1.6vw, 1.1rem); letter-spacing: 0.42em; text-transform: uppercase; color: #FFFFFF; }
.bf-logo--mini .bf-black, .bf-logo--mini .bf-friday { font-size: 1.6rem; }
.bf-logo--mini .bf-marca { margin-top: 0.35rem; font-size: 0.6rem; letter-spacing: 0.32em; }

.bf-data { display: flex; align-items: center; gap: 0.6rem; margin-top: 1.1rem; font-family: "Mundial", sans-serif; text-transform: uppercase; }
.bf-data svg { width: 1.4rem; height: 1.4rem; color: #D9B6E8; }
.bf-data .bf-dia { font-weight: 700; font-size: 1.7rem; color: #FD6A18; }
.bf-data .bf-mes { font-weight: 500; font-size: 1.35rem; letter-spacing: 0.28em; color: #FFFFFF; }

/* ---------- Formulário ---------- */
.bf-form { display: flex; flex-direction: column; gap: 0.9rem; max-width: 26rem; }
.bf-form p { margin: 0; font-size: 1.02rem; line-height: 1.55; color: #EDE4F5; }
.bf-form input {
  font: inherit; width: 100%; padding: 0.95rem 1.1rem;
  border-radius: 0.5rem; border: 0; background: #FFFFFF; color: #27272A;
}
.bf-form input::placeholder { color: #A1A1AA; }
.bf-form input:focus { outline: 3px solid #43E6EE; outline-offset: 2px; }
.bf-btn-verde {
  font-family: "Mundial", sans-serif; font-weight: 700; font-size: 0.95rem;
  letter-spacing: 0.12em; text-transform: uppercase; text-align: center; text-decoration: none;
  cursor: pointer; border: 0; border-radius:8px;
  padding: 1rem 1.6rem; color: #FFFFFF;
  background:#FD6A18;
  box-shadow:0 3px 0 #C94700;
  transition: transform 150ms ease, box-shadow 150ms ease;
  display: inline-flex; align-items: center; justify-content: center; gap: 0.55rem;
}
.bf-btn-verde:hover { transform: translateY(-2px); box-shadow:0 3px 0 #C94700; }
.bf-tag { margin: 0.4rem 0 0; font-size: 1.25rem; font-weight: 500; }
.bf-tag b { color: #FD6A18; }

/* ---------- Colagem da raposa ---------- */
.bf-glow { position: absolute; width: 82%; aspect-ratio: 1; border-radius: 999rem; background: radial-gradient(circle, rgba(145, 38, 197, 0.5) 0%, transparent 65%); }
.bf-colagem { position: relative; display: grid; place-items: center; min-height: 24rem; }
.bf-estrela {
  position: absolute; width: 78%; aspect-ratio: 1;
  background: linear-gradient(150deg, #BB52ED 0%, #72189E 55%, #FD6A18 130%);
  clip-path: polygon(50% 0%, 59% 12%, 72% 5%, 74% 20%, 89% 18%, 84% 32%, 100% 37%, 89% 50%, 100% 63%, 84% 68%, 89% 82%, 74% 80%, 72% 95%, 59% 88%, 50% 100%, 41% 88%, 28% 95%, 26% 80%, 11% 82%, 16% 68%, 0% 63%, 11% 50%, 0% 37%, 16% 32%, 11% 18%, 26% 20%, 28% 5%, 41% 12%);
  filter: drop-shadow(0 18px 40px rgba(145, 38, 197, 0.35));
}
.bf-estrela--amarela { width: 34%; background: linear-gradient(150deg, #43E6EE 0%, #22D3EE 100%); right: 4%; top: 2%; left: auto; }
.bf-raposa { position: relative; width: min(100%, 30rem); filter: drop-shadow(0 16px 34px rgba(0, 0, 0, 0.45)); }
.bf-adesivo {
  position: absolute; font-family: "Mundial", sans-serif; font-weight: 900; text-transform: uppercase;
  font-size: clamp(1.3rem, 2.6vw, 2rem); letter-spacing: 0.04em; color: #FD6A18;
  text-shadow: 3px 3px 0 #3C0E52, 5px 5px 0 rgba(0, 0, 0, 0.35);
}

/* ---------- Painel gradiente ---------- */
.bf-painel {
  position: relative; border-radius: 1.6rem; overflow: visible;
  max-width: 58rem; margin: 0 auto;
  background: linear-gradient(100deg, #551277 0%, #9126C5 48%, #E85A00 88%, #FD6A18 104%);
  padding: 2.8rem 3rem;
  display: grid; grid-template-columns: 1.15fr 0.85fr; gap: 2rem; align-items: center;
  box-shadow: 0 24px 60px rgba(85, 18, 119, 0.35);
}
.bf-painel h2 { margin: 0 0 0.9rem; font-size: clamp(1.6rem, 3vw, 2.2rem); font-weight: 800; line-height: 1.15; }
.bf-painel p { margin: 0 0 1.5rem; font-size: 1.02rem; line-height: 1.6; color: #FDF4FF; }
.bf-painel .bf-colagem { min-height: 18rem; }
.bf-painel .bf-raposa { width: min(88%, 20rem); margin-top: -4.5rem; }
.bf-painel h2 { color: #FFFFFF; }
.bf-painel p { color: #FDF4FF; }

/* ---------- Página "quase lá" ---------- */
.bf-central { max-width: 44rem; margin: 0 auto; text-align: center; }
.bf-central h1 { margin: 0 0 1rem; font-size: clamp(2.2rem, 5vw, 3.2rem); font-weight: 800; }
.bf-central h1 b { color: #FD6A18; font-weight: 800; }
.bf-central .bf-lede { margin: 0 0 2rem; font-size: 1.05rem; line-height: 1.6; color: #EDE4F5; }
.bf-passo-rotulo { margin: 0 0 1.2rem; font-family: "Mundial", sans-serif; font-weight: 500; font-size: 0.85rem; letter-spacing: 0.38em; text-transform: uppercase; color: #D9B6E8; }
.bf-passos { display: flex; flex-direction: column; gap: 1.2rem; margin-bottom: 1.8rem; }
.bf-passo {
  display: grid; grid-template-columns: 5.2rem 1fr; align-items: stretch; text-align: left;
  border: 1px solid rgba(255, 255, 255, 0.85); border-radius: 0.7rem; overflow: hidden;
  background: rgba(12, 5, 20, 0.55);
  box-shadow: 0 0 18px rgba(145, 38, 197, 0.5), inset 0 0 12px rgba(145, 38, 197, 0.14);
}
.bf-passo .bf-num {
  display: grid; place-items: center;
  font-family: "Mundial", sans-serif; font-weight: 900; font-size: 2rem; color: #FFFFFF;
  background: linear-gradient(180deg, #AE65CE 0%, #9126C5 100%);
}
.bf-passo .bf-texto { padding: 1.1rem 1.3rem; font-size: 0.98rem; line-height: 1.55; color: #F5EEFB; }
.bf-passo .bf-texto b { color: #FFFFFF; }

/* ---------- Faixas diagonais ---------- */
.bf-faixas { position: relative; height: 9rem; margin-top: 3rem; overflow: hidden; }
.bf-faixa {
  position: absolute; left: -4%; width: 108%; padding: 0.55rem 0;
  font-family: "Mundial", sans-serif; font-weight: 700; font-size: 1.05rem;
  letter-spacing: 0.14em; text-transform: uppercase; white-space: nowrap; overflow: hidden;
  color: #FFFFFF;
}
.bf-faixa .bf-bf { font-weight: 900; letter-spacing: 0.03em; }
.bf-faixa--roxa { top: 1.6rem; transform: rotate(2.6deg); background: linear-gradient(90deg, #551277, #9126C5); }
.bf-faixa--rosa { top: 4.6rem; transform: rotate(-2.2deg); background: linear-gradient(90deg, #E85A00, #FD6A18); z-index: 1; }

/* ---------- Rodapé ---------- */
.bf-rodape { background: #0A0410; padding: 2.2rem 0 2.6rem; }
.bf-rodape .bf-linha1 { display: flex; align-items: center; justify-content: space-between; gap: 1.5rem; flex-wrap: wrap; }
.bf-rodape .bf-contato { font-size: 0.8rem; color: #9B93A2; }
.bf-rodape hr { border: 0; border-top: 1px solid #2A1440; margin: 1.6rem 0; }
.bf-rodape .bf-linha2 { display: flex; justify-content: space-between; gap: 1rem; flex-wrap: wrap; font-size: 0.8rem; color: #9B93A2; }
.bf-rodape a { color: #9B93A2; text-decoration: none; }
.bf-rodape a:hover { color: #FFFFFF; }

/* ---------- Barra de preview da Vitrine ---------- */
.vt-volta {
  position: fixed; bottom: 1rem; left: 50%; transform: translateX(-50%); z-index: 50;
  background: rgba(16, 7, 29, 0.92); color: #FAFAFA; text-decoration: none;
  font-size: 0.85rem; font-weight: 600; font-family: "Mundial", sans-serif;
  padding: 0.55rem 1.1rem; border-radius: 999rem;
  box-shadow: 0 16px 48px rgba(16, 7, 29, 0.5); backdrop-filter: blur(6px);
}
.vt-volta:hover { background: rgba(60, 14, 82, 0.95); }

/* ---------- Responsivo ---------- */
@media (max-width: 56rem) {
  .bf-hero-grid { grid-template-columns: 1fr !important; gap: 2.5rem !important; }
  .bf-painel { grid-template-columns: 1fr; padding: 2rem 1.5rem; }
  .bf-painel .bf-raposa { margin-top: 0; }
  .bf-colagem { min-height: 19rem; }
  .bf-faixas { height: 7.5rem; }
  .bf-faixa { font-size: 0.85rem; }
}

/* Diagramação: conteúdo dos blocos puxado para o centro, como no bloco do Kit */
.bf-wrap.bf-hero-grid { max-width: 62rem; padding: 0 2rem; }
.bf-hero-grid > div:first-child { max-width: 30rem; }
.bf-colagem { min-height: 21rem; }

